/// The hand-over reply protocol of the merged compaction call (GOAL
/// #2394): the instruction renderer, the reply parser and the hide-label
/// sanitizer. Pure functions over text — no IO, no provider.
///
/// One call reads the last main request as sent (S0 — every record tagged
/// `m<N>`) plus ONE appended instruction ([renderHandOverInstruction]);
/// the reply is a hide list followed by `-` and the hand-over text
/// ([parseHandOverReply]). The model PROPOSES — the engine disposes (see
/// `hand_over_dispose.dart`); every label the model writes passes
/// [sanitizeHideLabel] before it can reach a marker.
library;

import '../summary_sanitizer.dart';

/// One hide proposal: the inclusive alias range `from`..`to` on the S0
/// epoch plus the model's raw label text (unsanitized).
final class HandOverHidePick {
  /// Creates a pick.
  const HandOverHidePick({
    required this.from,
    required this.to,
    required this.rawLabel,
  });

  /// The first alias of the range.
  final int from;

  /// The last alias of the range (equal to [from] for a single record).
  final int to;

  /// The label exactly as the model wrote it (empty when none).
  final String rawLabel;
}

/// A parsed hand-over reply.
final class HandOverReply {
  /// Creates a reply.
  const HandOverReply({
    required this.picks,
    required this.transfer,
    required this.ignoredLines,
  });

  /// The hide proposals in reply order, deduplicated.
  final List<HandOverHidePick> picks;

  /// The hand-over text after the `-` separator; `null` when the reply
  /// carried no text (hide-only, E5) or was empty.
  final String? transfer;

  /// Reply lines inside the hide prefix that named no usable alias
  /// (garbage or inverted ranges) — a count for the run log, never
  /// content.
  final int ignoredLines;

  /// Whether the reply proposed a hide-only run (no transfer text).
  bool get hideOnly => picks.isNotEmpty && transfer == null;
}

final RegExp _thinkBlocks = RegExp(
  r'<think>.*?</think>',
  dotAll: true,
  caseSensitive: false,
);
final RegExp _thinkOpenEnded = RegExp(
  r'<think>.*$',
  dotAll: true,
  caseSensitive: false,
);
final RegExp _zeroWidth = RegExp(r'[\u200B\u200C\u200D\u2060\uFEFF]');

/// Normalizes a reply's encoding noise (E1): BOM, zero-width characters
/// and CRLF line endings never reach the parser.
String normalizeReplyText(String text) => text
    .replaceAll(_zeroWidth, '')
    .replaceAll('\r\n', '\n')
    .replaceAll('\r', '\n');

/// Removes `<think>…</think>` blocks — and an unclosed `<think>` through
/// the end of the text — BEFORE parsing or persisting (E3): reasoning that
/// leaked into the text channel is never a hide id, never a transfer.
String stripThinkBlocks(String text) =>
    text.replaceAll(_thinkBlocks, '').replaceAll(_thinkOpenEnded, '');

// `(?![0-9])` binds the alias: an over-long digit run is not an alias.
final RegExp _rangeLine = RegExp(
  r'^\s*m?(\d{1,9})(?![0-9])\s*-\s*(\d{1,9})(?![0-9])(?:\s+-\s*|\s+)?(.*?)\s*$',
);
final RegExp _singleLine = RegExp(
  r'^\s*m?(\d{1,9})(?![0-9])(?:\s+-\s*|\s+)?(.*?)\s*$',
);
final RegExp _separatorLine = RegExp(r'^-{2,}$');

/// A hide-list range wider than this is a degenerate echo (the judge
/// parser's bound) and names nothing.
const int _maxRangeSpan = 10000;

/// Parses the model's hand-over reply (AC5).
///
/// The hide list is the MAXIMAL PREFIX of lines of the shape `N`, `N-M`
/// (inclusive range) plus an optional ` - ` / whitespace and a label:
/// - an inverted or over-long range is ignored (counted in
///   [HandOverReply.ignoredLines]); duplicates collapse (E2);
/// - a line of dashes (`-`, `---`) ends the list; the separator is
///   OPTIONAL — the first non-id, non-blank line after the list starts
///   the transfer (blank lines never end it);
/// - a FIRST line that is not an id and not the separator means NO hides
///   and the whole text is the transfer (the skeleton example `NN-NN`
///   returned verbatim lands here — E29);
/// - no text after the list → [HandOverReply.transfer] is `null`
///   (hide-only, E5).
HandOverReply parseHandOverReply(String text) {
  final normalized = stripThinkBlocks(normalizeReplyText(text)).trim();
  if (normalized.isEmpty) {
    return const HandOverReply(picks: [], transfer: null, ignoredLines: 0);
  }
  final lines = normalized.split('\n');
  final picks = <HandOverHidePick>[];
  final seen = <String>{};
  var ignored = 0;
  var index = 0;
  // Blank lines never end the list (a model often pads before the `-`);
  // the first non-blank line that names no alias does.
  while (index < lines.length) {
    final parsed = _hideListLine(lines[index], seen);
    picks.addAll([?parsed.pick]);
    if (parsed.ignored) {
      ignored++;
    }
    if (parsed.consumed) {
      index++;
    }
    if (parsed.ends) {
      break;
    }
  }
  if (index == 0) {
    // Not an id line and not a separator: no hides, whole text = transfer.
    return HandOverReply(
      picks: const [],
      transfer: normalized,
      ignoredLines: 0,
    );
  }
  final transfer = lines.sublist(index).join('\n').trim();
  return HandOverReply(
    picks: picks,
    transfer: transfer.isEmpty ? null : transfer,
    ignoredLines: ignored,
  );
}

/// One hide-list line: [pick] names an alias (deduplicated through
/// [seen]), [ignored] is an id line naming nothing usable, [ends] stops
/// the list (the separator, or a line that is no id at all), and
/// [consumed] says whether the line belongs to the list (a non-id line
/// starts the transfer itself).
({HandOverHidePick? pick, bool ignored, bool ends, bool consumed})
_hideListLine(String line, Set<String> seen) {
  final trimmed = line.trim();
  if (trimmed.isEmpty) {
    return (pick: null, ignored: false, ends: false, consumed: true);
  }
  if (trimmed == '-' || _separatorLine.hasMatch(trimmed)) {
    return (pick: null, ignored: false, ends: true, consumed: true);
  }
  final range = _rangeLine.firstMatch(line);
  final single = range == null ? _singleLine.firstMatch(line) : null;
  if (range == null && single == null) {
    return (pick: null, ignored: false, ends: true, consumed: false);
  }
  final parsed = _aliasLine(range ?? single!, isRange: range != null);
  final key = parsed.pick == null
      ? ''
      : '${parsed.pick!.from}-${parsed.pick!.to}';
  if (parsed.pick != null && !seen.add(key)) {
    return (pick: null, ignored: false, ends: false, consumed: true);
  }
  return (
    pick: parsed.pick,
    ignored: parsed.ignored,
    ends: false,
    consumed: true,
  );
}

/// An id line's pick: an inverted or over-long range is [ignored]
/// (counted, never content).
({HandOverHidePick? pick, bool ignored}) _aliasLine(
  RegExpMatch match, {
  required bool isRange,
}) {
  final from = int.parse(match.group(1)!);
  final to = isRange ? int.parse(match.group(2)!) : from;
  if (from <= 0 || to < from || to - from >= _maxRangeSpan) {
    return (pick: null, ignored: true);
  }
  return (
    pick: HandOverHidePick(
      from: from,
      to: to,
      rawLabel: (match.group(isRange ? 3 : 2) ?? '').trim(),
    ),
    ignored: false,
  );
}

final RegExp _labelLead = RegExp(r'^[-–—:]+\s*');
final RegExp _whitespaceRun = RegExp(r'\s+');
final RegExp _brackets = RegExp(r'[\[\]]');
final RegExp _numericEcho = RegExp(r'^m?\d+(?:-\d+)?(?:\s+m?\d+(?:-\d+)?)*$');

// Word boundaries that understand Cyrillic too: `\b` is ASCII-only.
const String _notWord = r'(?<![A-Za-z0-9А-Яа-яЁё])';
const String _notWordAfter = r'(?![A-Za-z0-9А-Яа-яЁё])';
final RegExp _secondPersonLabel = RegExp(
  '$_notWord(?:you|your|yours|yourself|u|ur|ты|тебя|твой|вы|вас|ваш|ваша|ваше|ваши|вам)'
  '$_notWordAfter',
  caseSensitive: false,
);
final RegExp _imperativeLabel = RegExp(
  '$_notWord(?:must|should|do not|don\'t|always|never|required|'
  r'обязательно|нужно|должен|должна|должно|запрещено|всегда|никогда)'
  '$_notWordAfter',
  caseSensitive: false,
);

/// The label budget (D3): one line, at most this many characters…
const int hideLabelMaxChars = 48;

/// …and at most this many words.
const int hideLabelMaxWords = 6;

/// Sanitizes a model-written hide label (D3/E35) into text safe to render
/// in every later request, or `null` (the marker then carries no label):
/// one whitespace-collapsed line without `[]`, ≤ [hideLabelMaxChars]
/// characters and ≤ [hideLabelMaxWords] words, no second person, no
/// imperative/imperative-shaped markers, no digits-only range echo — and
/// unchanged through the summary sanitizer's ephemeral arm (a label the
/// sanitizer would rewrite is not a label). NEVER stored as a message.
String? sanitizeHideLabel(String raw) {
  var label = raw
      .trim()
      .replaceFirst(_labelLead, '')
      .replaceAll(_whitespaceRun, ' ')
      .trim();
  if (label.isEmpty || label == '-') return null;
  if (_brackets.hasMatch(label)) return null;
  if (label.length > hideLabelMaxChars) return null;
  if (label.split(' ').length > hideLabelMaxWords) return null;
  if (_numericEcho.hasMatch(label)) return null;
  if (_secondPersonLabel.hasMatch(label)) return null;
  if (_imperativeLabel.hasMatch(label)) return null;
  if (sanitizeSummary(label).text != label) return null;
  return label;
}

final RegExp _placeholder = RegExp(r'\{\{(\w+)\}\}');

/// Renders the hand-over instruction from the prompt template (D13 —
/// `prompts.g.dart` carries no templating, the `{{…}}` tokens are
/// substituted here, at the call site). Deterministic: same inputs, same
/// text; an unknown token is left verbatim so a prompt edit naming a new
/// placeholder surfaces in the output instead of vanishing.
String renderHandOverInstruction({
  required String template,
  required int contextTokens,
  required int windowTokens,
  required int foldFrom,
  required int foldTo,
  List<String> openUserRequests = const [],
  String? pinnedOperative,
  String? foldedCheckpoints,
}) {
  final values = <String, String>{
    'context_tokens': '$contextTokens',
    'window_tokens': '$windowTokens',
    'fold_from': '$foldFrom',
    'fold_to': '$foldTo',
    'open_user_requests': openUserRequests.isEmpty
        ? 'none'
        : openUserRequests.join('\n'),
    'pinned_operative': pinnedOperative ?? '',
    'folded_checkpoints': foldedCheckpoints ?? '',
  };
  return template
      .replaceAllMapped(_placeholder, (match) => values[match[1]] ?? match[0]!)
      .trimRight();
}

final RegExp _userIntentHeading = RegExp(
  r'^(?:#{1,6}\s*)?(?:open user requests\b|open asks\b\s*:)',
  multiLine: true,
  caseSensitive: false,
);
final RegExp _askPointer = RegExp(r'^\s*-\s*\[[^\]]*\]\s*');

/// The verdict of the mechanical open-asks check (D2/#81).
typedef OpenUserRequestsVerdict = ({
  /// Whether the transfer carries the mandatory `## Open User Requests`
  /// (or `open asks:`) heading — without it the sanitizer belt cannot
  /// run, so the run FAILS.
  bool heading,

  /// Every `<open-user-requests>` line whose text (after the pointer,
  /// whitespace-flattened) is not present VERBATIM in the transfer.
  List<String> missing,
});

/// Verifies the hand-over text against the engine's mechanical
/// `<open-user-requests>` block (AC6): the heading must be present and
/// every ask line must survive verbatim; otherwise the run fails and
/// nothing is appended (E36).
OpenUserRequestsVerdict verifyOpenUserRequests(
  String transfer,
  List<String> askLines,
) {
  final flat = transfer.replaceAll(_whitespaceRun, ' ');
  final missing = <String>[];
  for (final line in askLines) {
    final text = line.replaceFirst(_askPointer, '').trim();
    if (text.isEmpty) continue;
    if (!flat.contains(text.replaceAll(_whitespaceRun, ' '))) {
      missing.add(text);
    }
  }
  return (heading: _userIntentHeading.hasMatch(transfer), missing: missing);
}

/// The engine DISPOSES over the model's hide proposals (GOAL #2394 AC7):
/// every alias the reply names resolves against the S0 SNAPSHOT index
/// (never a fresh ledger — aliases drift under windowed storage and hard
/// caps, ✗C/D7), the record is then validated against the FRESH projection
/// with the judge-era `validateHidePicks` semantics (snap OUTWARD to whole
/// pair groups, protected tail, pinned expansions, `·exempt` user turns),
/// plus the merged call's new rejections:
///
/// - `U` unknown — the alias names nothing on the frozen epoch index
///   (hallucinated, the live edge, beyond the index);
/// - `X` exempt — a real user turn is never hidden, whatever the model
///   wrote (F8/F9/E9);
/// - `T` tail/pin — the protected live edge or a pinned expansion;
/// - `C` covered/in-range — already hidden, checkpoint-covered, or inside
///   the fold range fixed before the call (moot: the checkpoint supersedes);
/// - `F` fold record — an old checkpoint / classic summary / branch
///   summary: hiding it would unfold its range and GROW pressure (E28);
/// - `S` snapped — the pick (plus its whole pair group) is hidden.
///
/// Pure — no IO; the engine appends the verdict's ids.
library;

import '../../session/session_record.dart';
import '../../context.dart';
import 'hand_over.dart';
import 'ledger.dart';
import 'projection.dart';

/// Where one hide proposal landed.
enum HidePickBucket {
  /// Hidden (snapped outward to the whole pair group).
  snapped,

  /// Unknown alias on the snapshot index.
  unknown,

  /// A real user turn.
  exempt,

  /// Protected tail or a pinned expansion.
  tail,

  /// Already hidden/covered or inside the fold range (moot).
  covered,

  /// A fold record (checkpoint / classic summary / branch summary).
  foldRecord,
}

/// The dispose verdict over one hand-over reply's hide list.
final class HandOverDisposeVerdict {
  /// Creates a verdict.
  const HandOverDisposeVerdict({
    required this.recordIds,
    required this.labels,
    required this.counts,
  });

  /// The stable record ids to hide — every surviving pick's WHOLE pair
  /// group, deduplicated, sorted.
  final List<String> recordIds;

  /// Sanitized label per CARRIER record id (the group's first record in
  /// file order); a pick whose label failed sanitization carries none.
  final Map<String, String> labels;

  /// Picks per bucket (every pick lands in exactly one).
  final Map<HidePickBucket, int> counts;

  /// Picks that produced ids.
  int get snapped => counts[HidePickBucket.snapped] ?? 0;

  /// Picks that named nothing on the snapshot index.
  int get unknown => counts[HidePickBucket.unknown] ?? 0;

  /// Picks that named a real user turn.
  int get exempt => counts[HidePickBucket.exempt] ?? 0;

  /// Picks that named the protected tail or a pinned expansion.
  int get tail => counts[HidePickBucket.tail] ?? 0;

  /// Picks that were moot (hidden / covered / inside the fold range).
  int get covered => counts[HidePickBucket.covered] ?? 0;

  /// Picks that named a fold record.
  int get foldRecord => counts[HidePickBucket.foldRecord] ?? 0;

  /// The report's hide-list line: `P → S snapped · U unknown · …` with
  /// the zero buckets omitted.
  String render() {
    final parts = <String>[
      '$snapped snapped',
      if (unknown > 0) '$unknown unknown',
      if (exempt > 0) '$exempt exempt',
      if (tail > 0) '$tail tail/pin',
      if (covered > 0) '$covered covered/in-range',
      if (foldRecord > 0) '$foldRecord fold-record',
    ];
    return parts.join(' · ');
  }
}

/// Disposes the reply's [picks].
///
/// [snapshotIndex] is the S0 epoch's `RecordSeqIndex` (alias → record);
/// [ledger] the FRESH view's ledger (pair groups, `exempt`), [state] the
/// fresh structured view (hidden / covered / pinned), [protectedTail] the
/// live-edge ids, [foldFromSeq]..[foldToSeq] the fold range fixed before
/// the call — or, when the engine knows the exact members, [inRangeSeqs]
/// (a pinned record INSIDE the span is not a member: hiding it is legal,
/// so the span alone would mis-bucket it as moot). Never throws: a pick
/// that names nothing lands in `U`.
HandOverDisposeVerdict disposeHidePicks({
  required List<HandOverHidePick> picks,
  required RecordSeqIndex snapshotIndex,
  required ContextLedger ledger,
  required StructuredViewState state,
  required Set<String> protectedTail,
  required int foldFromSeq,
  required int foldToSeq,
  Set<int>? inRangeSeqs,
}) {
  final entryById = {for (final entry in ledger.entries) entry.recordId: entry};
  final counts = {for (final bucket in HidePickBucket.values) bucket: 0};
  final ids = <String>{};
  final labels = <String, String>{};
  for (final pick in picks) {
    final resolved = <SessionRecord>[
      // Aliases beyond the frozen index resolve to nothing (`null`).
      for (var seq = pick.from; seq <= pick.to; seq++)
        ?snapshotIndex.recordAt(seq),
    ];
    final bucket = _bucketOf(
      resolved,
      ledger: ledger,
      entryById: entryById,
      state: state,
      protectedTail: protectedTail,
      foldFromSeq: foldFromSeq,
      foldToSeq: foldToSeq,
      inRangeSeqs: inRangeSeqs,
      snapshotIndex: snapshotIndex,
    );
    counts[bucket] = counts[bucket]! + 1;
    if (bucket != HidePickBucket.snapped) continue;
    final group = <String>{
      for (final record in resolved) ...ledger.groupOf(record.id),
    };
    ids.addAll(group);
    final label = sanitizeHideLabel(pick.rawLabel);
    if (label != null) {
      labels.putIfAbsent(_carrierOf(group, snapshotIndex), () => label);
    }
  }
  return HandOverDisposeVerdict(
    recordIds: ids.toList()..sort(),
    labels: labels,
    counts: counts,
  );
}

HidePickBucket _bucketOf(
  List<SessionRecord> resolved, {
  required ContextLedger ledger,
  required Map<String, LedgerEntry> entryById,
  required StructuredViewState state,
  required Set<String> protectedTail,
  required int foldFromSeq,
  required int foldToSeq,
  required Set<int>? inRangeSeqs,
  required RecordSeqIndex snapshotIndex,
}) {
  if (resolved.isEmpty) return HidePickBucket.unknown;
  if (resolved.any(isFoldRecord)) return HidePickBucket.foldRecord;
  bool moot(SessionRecord record) {
    if (state.hiddenRecordIds.contains(record.id) ||
        state.isCovered(record.id)) {
      return true;
    }
    final seq = snapshotIndex.seqOf(record.id);
    if (seq == null) return false;
    return inRangeSeqs != null
        ? inRangeSeqs.contains(seq)
        : seq >= foldFromSeq && seq <= foldToSeq;
  }

  // The fresh ledger's `·exempt` (a real user turn); a record the ledger
  // does not list falls back to its own shape.
  bool isExempt(SessionRecord record) =>
      entryById[record.id]?.exempt ??
      (record is MessageRecord && record.message is UserMessage);

  final live = [
    for (final record in resolved)
      if (!moot(record)) record,
  ];
  if (live.isEmpty) return HidePickBucket.covered;
  if (live.any(isExempt)) {
    return HidePickBucket.exempt;
  }
  bool touchesTailOrPin(String id) =>
      protectedTail.contains(id) || state.pinnedRecordIds.contains(id);
  if (live.any((record) => touchesTailOrPin(record.id))) {
    return HidePickBucket.tail;
  }
  // Snap OUTWARD to the whole pair group (D6): a group that touches the
  // tail or a pin hides as a whole or never.
  for (final record in live) {
    for (final member in ledger.groupOf(record.id)) {
      if (touchesTailOrPin(member)) return HidePickBucket.tail;
    }
  }
  return HidePickBucket.snapped;
}

/// Whether [record] is a fold record (E28): its HIDE would render it
/// without a marker and unfold the range it replaces.
bool isFoldRecord(SessionRecord record) =>
    record is CompactCheckpointRecord ||
    record is CompactionRecord ||
    record is BranchSummaryRecord;

/// An alias no record can carry (file aliases are small counters) — the
/// sort key of a member missing from the snapshot index. A 30-bit
/// literal: dart2js shifts wrap at 32 (issue #1074 guard).
const int _beyondLastSeq = 1 << 30;

/// The group's carrier: the member with the smallest alias (file order).
String _carrierOf(Set<String> group, RecordSeqIndex snapshotIndex) {
  String? carrier;
  var carrierSeq = _beyondLastSeq;
  for (final id in group) {
    final seq = snapshotIndex.seqOf(id) ?? _beyondLastSeq;
    if (seq < carrierSeq) {
      carrierSeq = seq;
      carrier = id;
    }
  }
  return carrier ?? group.first;
}

/// The hand-over call's robustness ladder (GOAL #2394 D1 — AC4): ONE
/// logical call over the S0 prefix + the appended instruction, at most
/// three round-trips, and NO fallback — neither to the classic prefix
/// compactor nor to any judge ladder. Every rung keeps the prefix
/// byte-identical (`[...S0.messages, instruction]`), so the provider
/// serves it from the bucket the main request just warmed:
///
/// - (a) an answer carrying tool calls (an adapter without `tool_choice`
///   or a model that disobeyed) → ONE nudge message appended after the
///   instruction; the tool-call answer itself is never appended (it would
///   orphan its calls); tools stay in the request — a tool-less retry
///   would break the prefix and the bucket (N4);
/// - (b) a provider error / network drop rides the global transient
///   retry that already wraps every host's catalog stream — same body,
///   same prefix; what still fails is a failure;
/// - (c) `stopReason == length` → ONE retry of the same request with the
///   output budget doubled; a second `length` is exhausted;
/// - (d) the output budget is explicit (`compaction.handOver.maxTokens`,
///   default [handOverMaxTokensDefault]);
/// - (e) an exhausted ladder is a FAILED call: the engine appends nothing
///   and reports loudly; the engine never changes.
library;

import '../../agent/agent_loop.dart' show StreamCallShape, StreamFunction;
import '../../cancel_token.dart' show CancelToken;
import '../../context.dart';
import '../../exceptions.dart' show CompactionException;
import '../../model.dart' show Model;
import '../../types.dart';
import '../cache_policy.dart';

/// The default output budget of the hand-over call
/// (`compaction.handOver.maxTokens`, D1 (d)).
const int handOverMaxTokensDefault = 8192;

/// The ONE nudge appended after a tool-call answer (D1a) — text only,
/// never the tool-call message itself.
const String handOverNudgeText =
    'Answer with the hide list and the hand-over text only; no tool calls.';

/// The final outcome of the ladder.
final class HandOverCallResult {
  const HandOverCallResult._({
    this.response,
    this.failure,
    required this.calls,
    required this.nudges,
    required this.budgetRetries,
    this.cacheHitRatio,
  });

  /// The usable answer (text, stopped normally), `null` on failure.
  final AssistantMessage? response;

  /// The failure — a provider/stream error or the exhausted-ladder
  /// verdict; `null` on success.
  final Object? failure;

  /// Real round-trips this logical call consumed (nudge and budget retry
  /// included) — the report's `calls`.
  final int calls;

  /// Nudge round-trips (0 or 1).
  final int nudges;

  /// Output-budget retries (0 or 1).
  final int budgetRetries;

  /// The share of input tokens the provider served from cache across the
  /// call's round-trips — `null` when the provider reported no usage
  /// (never a fake zero, gh-2097).
  final double? cacheHitRatio;

  /// Whether the call produced a usable answer.
  bool get ok => failure == null && response != null;
}

/// The engine-facing hand-over call: the S0 context with the instruction
/// already appended as its last message.
typedef HandOverCall =
    Future<HandOverCallResult> Function(
      Context context, {
      CancelToken? cancelToken,
    });

/// Builds the [HandOverCall] adapter over a provider [stream] and the
/// session's [model]. Routing is the policy's ([CompactionCachePolicy
/// .sessionAffine] — the session's own bucket through NULL fallthrough);
/// the request shape (`tool_choice: none`, the output budget, the history
/// breakpoint at [prefixLength] = S0's last message, the pinned Copilot
/// initiator) travels in the same zone. [onDelta] mirrors text/thinking
/// deltas to the host's busy row; [onUsage] receives every round-trip's
/// provider usage.
HandOverCall handOverCallAdapter({
  required StreamFunction stream,
  required Model model,
  required CompactionCachePolicy cachePolicy,
  int maxTokens = handOverMaxTokensDefault,
  required int prefixLength,
  String? copilotInitiator,
  void Function(String delta)? onDelta,
  void Function(Usage usage)? onUsage,
}) {
  return (Context context, {CancelToken? cancelToken}) async {
    // The prefix is copied once; only the nudge ever appends to it.
    var messages = List<Message>.of(context.messages);
    var budget = maxTokens;
    var nudges = 0;
    var budgetRetries = 0;
    var calls = 0;
    final usage = CompactionUsageAccumulator();
    HandOverCallResult fail(Object failure) => HandOverCallResult._(
      failure: failure,
      calls: calls,
      nudges: nudges,
      budgetRetries: budgetRetries,
      cacheHitRatio: usage.snapshot().cacheHitRatio,
    );
    while (true) {
      final AssistantMessage response;
      try {
        response = await _handOverRoundTrip(
          stream: stream,
          model: model,
          cachePolicy: cachePolicy,
          context: context,
          messages: messages,
          budget: budget,
          prefixLength: prefixLength,
          copilotInitiator: copilotInitiator,
          cancelToken: cancelToken,
          onDelta: onDelta,
        );
      } on Object catch (error) {
        // A throwing StreamFunction breaks the never-throw contract — the
        // pipeline is defensive anyway.
        return fail(error);
      }
      calls++;
      _foldUsage(response, onUsage, usage);
      final stopFailure = _stopFailure(response);
      if (stopFailure != null) return fail(stopFailure);
      if (_hasToolCalls(response) && nudges >= 1) {
        return fail(
          const CompactionException(
            'hand-over call returned tool calls again after the nudge '
            '(ladder exhausted)',
          ),
        );
      }
      if (_hasToolCalls(response)) {
        // ONE nudge: the instruction's "do not call any tools" restated,
        // appended as a user turn (the prefix stays byte-stable).
        nudges++;
        messages = [...messages, UserMessage.text(handOverNudgeText)];
        continue;
      }
      if (response.stopReason == StopReason.length) {
        if (budgetRetries >= 1) {
          return fail(
            CompactionException(
              'hand-over call hit the output budget twice '
              '($budget tokens; ladder exhausted)',
            ),
          );
        }
        // ONE retry at twice the budget.
        budgetRetries++;
        budget *= 2;
        continue;
      }
      return HandOverCallResult._(
        response: response,
        calls: calls,
        nudges: nudges,
        budgetRetries: budgetRetries,
        cacheHitRatio: usage.snapshot().cacheHitRatio,
      );
    }
  };
}

/// ONE round-trip: the request shape in the zone (NULL tool choice, the
/// budget, the prefix breakpoint), the deltas forwarded to the host, the
/// completed message back. A throwing stream propagates (the caller
/// folds it into the call's failure).
Future<AssistantMessage> _handOverRoundTrip({
  required StreamFunction stream,
  required Model model,
  required CompactionCachePolicy cachePolicy,
  required Context context,
  required List<Message> messages,
  required int budget,
  required int prefixLength,
  required String? copilotInitiator,
  required CancelToken? cancelToken,
  required void Function(String delta)? onDelta,
}) async {
  final shape = StreamCallShape(
    toolChoice: 'none',
    maxTokens: budget,
    prefixLength: prefixLength,
    copilotInitiator: copilotInitiator,
  );
  final events = cachePolicy.runWith(
    () => stream(
      model,
      Context(
        systemPrompt: context.systemPrompt,
        messages: messages,
        tools: context.tools,
      ),
      cancelToken: cancelToken,
    ),
    CompactionCallClass.handOver,
    shape: shape,
  );
  if (onDelta != null) {
    events.listen((event) {
      final delta = _deltaOf(event);
      if (delta.isNotEmpty) onDelta(delta);
    });
  }
  return events.result;
}

String _deltaOf(AssistantMessageEvent event) => switch (event) {
  TextDeltaEvent(:final delta) => delta,
  ThinkingDeltaEvent(:final delta) => delta,
  _ => '',
};

/// The ladder's terminal verdicts on a stop reason: a provider error or
/// an abort fails at once (the `length` stop is the caller's ONE budget
/// retry, `null` here).
CompactionException? _stopFailure(AssistantMessage response) =>
    switch (response.stopReason) {
      StopReason.error => CompactionException(
        'hand-over call failed: ${response.errorMessage ?? 'unknown error'}',
      ),
      StopReason.aborted => CompactionException(
        'hand-over call aborted: ${response.errorMessage ?? 'aborted'}',
      ),
      _ => null,
    };

/// Whether the answer carries tool calls (whatever the stop reason says —
/// an adapter may stop `end_turn` with a tool_use block in some SDKs).
bool _hasToolCalls(AssistantMessage response) =>
    response.content.any((block) => block is ToolCall);

/// Forwards one round-trip's usage to the host sink (zero usage reports
/// nothing) and folds it into the call's cache ratio.
void _foldUsage(
  AssistantMessage response,
  void Function(Usage usage)? sink,
  CompactionUsageAccumulator into,
) {
  final usage = response.usage;
  if (usage.totalTokens == 0 &&
      usage.input == 0.0 &&
      usage.cacheRead == 0.0 &&
      usage.cacheWrite == 0.0) {
    return;
  }
  sink?.call(usage);
  into.add(usage);
}

