/// The marker for one hidden record: `[3:hidden·tool_result·4.2k]`, plus
/// the bounded content preview when one is known (issue #266 F4):
/// `[3:hidden·tool_result·4.2k·"first line…"]`.
String hiddenMarker({
  required int seq,
  required String kind,
  required int tokens,
  String? preview,
  bool pinned = false,
