      coveredIds.addAll(view_.ledger.groupOf(member.recordId));
    }
    return _CkptRange(
      firstRecordId: members.first.recordId,
      lastRecordId: members.last.recordId,
      coveredRecordIds: coveredIds.toList()..sort(),
      state: view_.state,
      visible: view_.visible,
      seqs: view_.seqs,
    );
  }

  bool _sharesGroup(
    List<_ProjectedEntry> entries,
    int cut,
    ContextLedger ledger,
  ) {
    if (cut >= entries.length) return false;
    return ledger
        .groupOf(entries[cut - 1].recordId)
        .contains(entries[cut].recordId);
  }

  /// Depth-cap flattening (D5): when the new checkpoint would nest deeper
  /// than [depthCap], the covered checkpoints already at the cap fold
  /// their text into the new prompt; their ids persist as flattened and
  /// become dead nodes for future depth computation.
  List<CompactCheckpointRecord> _flattenForDepthCap(_CkptRange range) {
    final byId = {for (final ckpt in range.state.checkpoints) ckpt.id: ckpt};
    final covered = range.coveredRecordIds.toSet();
    return [
      for (final ckpt in range.state.checkpoints)
        if (covered.contains(ckpt.id) && _depthOf(ckpt, byId, {}) >= depthCap)
          ckpt,
    ];
  }

  int _depthOf(
    CompactCheckpointRecord ckpt,
    Map<String, CompactCheckpointRecord> byId,
    Set<String> visiting,
  ) {
    if (!visiting.add(ckpt.id)) return 1; // Cycle defense: treat as leaf.
    var depth = 1;
    for (final id in ckpt.coversRecordIds) {
      final inner = byId[id];
      if (inner == null) continue;
      if (ckpt.flattenedRecordIds.contains(id)) continue; // Dead node.
      final innerDepth = _depthOf(inner, byId, visiting);
      if (innerDepth + 1 > depth) depth = innerDepth + 1;
    }
    visiting.remove(ckpt.id);
    return depth;
  }

  /// Summarizes one checkpoint range. Returns the summary text (`null` on
  /// failure-safety) together with the REAL number of summarizer calls the
  /// fold made — 0 for the deterministic marker-only consolidation
  /// (issue #387), 1 for a single in-window call, N for a #729 chunked
  /// fold — so pass receipts can report actual work instead of a hardcoded
  /// `1` (gh-2044 review thread 4).
  Future<({String? text, int summarizerCalls})> _summarizeRange(
    _CkptRange range,
    List<CompactCheckpointRecord> flattened,
  ) async {
    final rangeRecords = <MessageRecord>[
      for (final record in range.visible)
        if (range.coveredRecordIds.contains(record.id) &&
            record is MessageRecord)
          record,
    ];
    final messages = [for (final record in rangeRecords) record.message];
    final coversSeqs = <int>[];
    for (final id in range.coveredRecordIds) {
      final seq = range.seqs.seqOf(id);
      if (seq != null) coversSeqs.add(seq);
    }
    final coversRanges = idsToRanges(coversSeqs);
    // Issue #387 marker consolidation: a range with no visible message
    // records folds a pure marker run — nothing is left to summarize, so
    // a deterministic note replaces the LLM call. Every id stays
    // expandable (the covers list still names them); the summarizer is
    // never invoked on marker-only ranges.
    if (rangeRecords.isEmpty) {
      return (
        text:
            'Earlier records already hidden behind expand markers '
            '(${idsToRanges(coversSeqs)}) were consolidated here to bound '
            'marker overhead. Use compact_expand on any id to reopen a '
            'record.',
        summarizerCalls: 0,
      );
    }
    final openAsks = userRequestCandidateLines(
      messages,
      recordIds: [for (final record in rangeRecords) record.id],
    );
    // Identity map for chunk-scoped open asks (#729 E2): the whole-range
    // ask lines are #81-uncapped, so riding them in every chunk's envelope
    // can exceed the budget on its own. Each chunk carries only its own
    // asks; earlier ones survive through the threaded fold, which the
    // `<covers>` instruction tells to restate them.
    final askIdOf = <Message, String>{
      for (final record in rangeRecords)
        if (record.message.role == 'user') record.message: record.id,
    };
    List<String> asksFor(List<Message> chunk) => userRequestCandidateLines(
      [
        for (final m in chunk)
          if (askIdOf.containsKey(m)) m,
      ],
      recordIds: [
        for (final m in chunk)
          if (askIdOf.containsKey(m)) askIdOf[m]!,
      ],
    );

    String build(String conversation, List<String> asks, String? priorFold) {
      final prompt = StringBuffer()
        ..writeln('<conversation>')
        ..writeln(conversation)
        ..writeln('</conversation>')
        ..writeln(
          '<covers>The checkpoint replaces these expand ids: '
          '$coversRanges. List them in your summary.</covers>',
        );
      if (asks.isNotEmpty) {
        prompt
          ..writeln('<open-user-requests>')
          ..writeln(asks.join('\n'))
          ..writeln('</open-user-requests>');
      }
      // gh-1409 E7: the verbatim-preserve block rides every checkpoint
      // prompt (and every chunk of a chunked fold — `build` builds those
      // too), before the folded checkpoints it must not paraphrase over.
      if (pinnedOperativeBlock != null) {
        prompt
          ..writeln(pinnedOperativeBlock)
          ..writeln();
      }
      for (final folded in flattened) {
        prompt
          ..writeln('<folded-checkpoint>')
          // Issue #1131: older persisted checkpoints re-enter this prompt
          // verbatim — heal them so poison cannot be paraphrased forward.
          // gh-1409: pins inside heal protected (AC4).
          ..writeln(
            sanitizeSummary(folded.text, protectedLines: pinnedLines).text,
          )
          ..writeln('</folded-checkpoint>');
      }
      if (priorFold != null) {
        // Issue #729 chunked fold: the running summary of the chunks
        // summarized so far rides the same folded-checkpoint envelope the
        // depth-cap flattening uses.
        prompt
          ..writeln('<folded-checkpoint>')
          ..writeln(priorFold)
          ..writeln('</folded-checkpoint>');
      }
      prompt.writeln(checkpointPrompt);
      return prompt.toString();
    }

    final budget = summarizerWindow == null
        ? null
        : summarizationPayloadBudget(summarizerWindow!, settings);
    // gh-2103: the fold's transcript rides the sanitize belt — the
    // checkpoint's user-intent lines are graded against what the summarizer
    // actually saw.
    final origins = SummaryOriginEvidence(messages);
    var prompt = build(serializeConversation(messages), openAsks, null);
    if (budget != null && estimateStringTokens(prompt) > budget) {
      // Issue #729: the dropped region does not fit the summarizer's
      // window — summarize chunk-wise and thread each chunk's summary into
      // the next, so the request that finally lands is bounded even when
      // the whole checkpoint range is not.
      return _chunkedFold(
        messages,
        build: build,
        asksFor: asksFor,
        budget: budget,
        origins: origins,
      );
    }
    final text = await _callSummarizer(prompt, origins: origins);
    return (text: text, summarizerCalls: 1);
  }

  /// The #729 chunked fold: splits [messages] into budget-sized chunks and
  /// folds them chunk-wise — each chunk's summary rides the next prompt via
  /// [priorFold] (`<folded-checkpoint>`), the last fold becomes the range
  /// summary. A summarizer failure mid-fold is failure-safe (`null`).
  Future<({String? text, int summarizerCalls})> _chunkedFold(
    List<Message> messages, {
    required String Function(
      String conversation,
      List<String> asks,
      String? priorFold,
    )
    build,
    required List<String> Function(List<Message> chunk) asksFor,
    required int budget,
    SummaryOriginEvidence? origins,
  }) async {
    var priorFold = '';
    var calls = 0;
    final chunks = chunkSummarizableMessages(
      messages,
      max(budget - _checkpointEnvelopeReserveTokens, 256),
    );
    for (final chunk in chunks) {
      var conversation = serializeConversation(chunk);
      final empty = build('', const [], priorFold.isEmpty ? null : priorFold);
      final envelopeChars = empty.length - 1; // minus writeln('')'s newline
      conversation = truncateForSummaryBudget(
        conversation,
        budgetTokens: budget,
        envelopeChars: envelopeChars,
      );
      final text = await _callSummarizer(
        build(
          conversation,
          asksFor(chunk),
          priorFold.isEmpty ? null : priorFold,
        ),
        origins: origins,
      );
      calls++;
      if (text == null) return (text: null, summarizerCalls: calls);
      priorFold = text;
    }
    return (text: priorFold, summarizerCalls: calls);
  }

  /// One summarizer call under the attempt budget (issue #515). Returns
  /// the trimmed summary text, `null` on failure-safety (empty/failed).
  /// [origins] (gh-2103) grades the provenance belt against the fold's
  /// transcript when provided.
  Future<String?> _callSummarizer(
    String prompt, {
    SummaryOriginEvidence? origins,
  }) async {
    try {
      final result =
          await summarize(
            SummarizationRequest(prompt: prompt, cancelToken: _effectiveToken),
          ).timeout(
            attemptBudget,
            onTimeout: () {
              final timeout = _budgetTimeout(
                'checkpoint summarizer',
                attemptBudget,
              );
              budgetSource?.cancel(timeout);
              throw timeout;
            },
          );
      final text = result.text?.trim();
      if (text == null || text.isEmpty) return null;
      // Issue #1131: checkpoints re-render every turn — strip ephemeral,
      // time-scoped claims the summarizer may have copied from context.
      // gh-1409 AC4: pin-carrying lines are exempt (the pin rides in the
      // envelope, structurally protected; raw lines protected here too).
      // gh-2103: the provenance belt rides the fold's origin evidence.
      return sanitizeSummary(
        text,
        protectedLines: pinnedLines,
        origins: origins,
      ).text;
    } on TimeoutException {
      // A budget kill surfaces as a named error (issue #515) — the pass
      // loop must not dissolve it into the failure-safety null.
      rethrow;
    } catch (_) {
      return null;
    }
  }
}

/// Envelope reserve for a chunked checkpoint prompt (issue #729): tags,
/// covers line, open asks, folded checkpoints and the instruction tail.
/// The exact per-chunk fit is enforced by the measured envelope truncation
/// in [_summarizeRange]; this only sizes the chunk plan.
const _checkpointEnvelopeReserveTokens = 2048;

/// Applies the classic compaction cut to a branch path: everything before
/// the LAST [CompactionRecord]'s first-kept entry drops away, the
/// [CompactionRecord] itself (its summary) heads the result. A path with
/// no classic compaction passes through unchanged.
List<SessionRecord> classicTransform(List<SessionRecord> path) {
  CompactionRecord? compaction;
  for (final entry in path) {
    if (entry is CompactionRecord) compaction = entry;
  }
  if (compaction == null) return [...path];
  final entries = <SessionRecord>[compaction];
  final index = path.indexOf(compaction);
  var foundFirstKept = false;
  for (var i = 0; i < index; i++) {
    if (path[i].id == compaction.firstKeptEntryId) foundFirstKept = true;
    if (foundFirstKept) entries.add(path[i]);
  }
  for (var i = index + 1; i < path.length; i++) {
    entries.add(path[i]);
  }
  return entries;
}

final class _LedgerView {
  const _LedgerView(
    this.ledger,
    this.state,
    this.visible,
    this.seqs,
    this.path,
  );

  final ContextLedger ledger;
  final StructuredViewState state;
  final List<SessionRecord> visible;
  final RecordSeqIndex seqs;

  /// The whole (post-classic-transform) branch: visible AND hidden
  /// records. The checkpoint walk projects this to weigh hidden records
  /// at their marker size (issue #387 consolidation).
  final List<SessionRecord> path;
}

/// One record in the projected checkpoint walk: its id and its wire
/// cost (payload tokens for visible records, marker tokens for hidden).
final class _ProjectedEntry {
  const _ProjectedEntry(this.recordId, this.tokens);

  final String recordId;
  final int tokens;
}

final class _CkptRange {
  const _CkptRange({
    required this.firstRecordId,
    required this.lastRecordId,
    required this.coveredRecordIds,
    required this.state,
    required this.visible,
    required this.seqs,
  });

  final String firstRecordId;
  final String lastRecordId;
  final List<String> coveredRecordIds;
  final StructuredViewState state;
  final List<SessionRecord> visible;
  final RecordSeqIndex seqs;
}

/// The `record_tag` wire protocol (GOAL #2394, Compaction 2.0 v2.1).
///
/// Every visible session record rides the wire prefixed with its file
/// alias — `m<seq> ` (`m142 toolResult(bash): …`) — so the model can
/// ADDRESS records in a hand-over reply ("hide 142-143") and the engine
/// can resolve those numbers back to stable record ids through the
/// SNAPSHOT index of the request the model actually saw.
///
/// Invariants (I4):
/// - a tag is wire-only: it is stamped on a COPY of the transcript right
///   before the request transforms, never on the transcript itself, never
///   persisted (`Context.toJson` is untouched);
/// - inside a tag epoch (the projection the transcript was rebuilt from)
///   the head messages carry their exact alias and the bytes are stable;
///   messages appended after the epoch started (the run's live edge —
///   the prompt, nudges, this run's answers and tool results) carry NO
///   tag: they are not records of this epoch yet (persistence is
///   asynchronous) and the model does not address them. The next epoch
///   (the next run's projection rebuild) tags them — one uncached
///   segment at the run boundary (E30), visible in the main request's
///   cache metric and the accepted conservative default of the card;
/// - non-records (the obligations / working-set tail blocks, `time-left:`
///   lines, carrier pins, the hand-over instruction) never carry a tag;
/// - tags exist only under the structured engine (`compaction.engine`).
///
/// Pure Dart — no IO; the transcript seq map is built by the session
/// projection (`Session.buildTranscriptProjection`).
library;

import '../context.dart';
import '../types.dart';
import 'structured/projection.dart' show RecordSeqIndex;

/// The pressure-basis cost of one record tag: `m142 ` is 2 tiktoken
/// tokens (o200k) and ≤ 5 for six-digit aliases — the budget pinned for
/// the `tagOverhead` term of the request estimate (D14).
const int recordTagTokens = 5;

/// The maximum alias the 5-token budget covers (`m999999 `).
const int _recordTagMaxSeq = 999999;

final RegExp _recordTagLineStart = RegExp(r'^m(\d+) ');
final RegExp _recordTagEchoLines = RegExp(r'^m\d+ +', multiLine: true);

/// The wire form of record [seq]: `m<seq>`.
String recordTag(int seq) => 'm$seq';

/// The seq a [text] opens with (`m142 rest` → 142), else `null`.
int? leadingRecordTag(String text) {
  final match = _recordTagLineStart.firstMatch(text);
  if (match == null) return null;
  final seq = int.tryParse(match.group(1)!);
  return seq != null && seq > 0 && seq <= _recordTagMaxSeq ? seq : null;
}

/// Whether [text] opens with a record tag (a tagged record line).
bool hasRecordTag(String text) => leadingRecordTag(text) != null;

/// Whether [message] is a record copy whose first text block opens with a
/// tag (the stamping is idempotent: a tagged copy is returned as is).
bool messageHasRecordTag(Message message) =>
    leadingRecordTag(firstTextOf(message)) != null;

/// The text of [message]'s first text block ('' when it has none).
String firstTextOf(Message message) {
  final blocks = messageBlocks(message);
  for (final block in blocks) {
    if (block is TextContent) return block.text;
  }
  return '';
}

/// The content blocks of [message] (a plain-string user message is a
/// one-text-block list; unknown shapes fold to empty).
List<ContentBlock> messageBlocks(Message message) => switch (message) {
  UserMessage(:final content) when content is List => [
    for (final block in content) block,
  ],
  UserMessage(:final content) => [TextContent(text: content as String)],
  ToolResultMessage(:final content) => content,
  AssistantMessage(:final content) => content,
  _ => const [],
};

/// Removes every leading `m<N> ` tag from the start of [text]'s lines —
/// the persist-side echo hygiene (E16): a hand-over text that repeated
/// the wire tags carries none once stored.
String stripRecordTags(String text) => text.replaceAll(_recordTagEchoLines, '');

/// One transcript build: the projected messages plus the record alias each
/// message projects from (aligned by index, `null` = a non-record) and
/// the file-order index the aliases resolve against — the tag epoch the
/// agent stamps requests from.
final class TranscriptProjection {
  /// Creates the projection; [recordSeqs] runs parallel to [messages].
  const TranscriptProjection({
    required this.messages,
    required this.recordSeqs,
    required this.index,
  });

  /// The projected transcript (`buildContextMessages` output).
  final List<Message> messages;

  /// The record alias per message, aligned by index (`null` = non-record).
  final List<int?> recordSeqs;

  /// The file-order record index the aliases resolve against.
  final RecordSeqIndex index;

  /// The tag epoch over this projection.
  TranscriptSeqMap get seqMap =>
      TranscriptSeqMap(headSeqs: recordSeqs, index: index);
}

/// The aligned record aliases of a transcript plus the epoch index they
/// resolve against — `null` marks a non-record (level-0 tail blocks,
/// instructions, notices) AND the live edge (messages appended since the
/// epoch started: untaged until the next epoch).
final class TranscriptSeqMap {
  /// Creates the map of one tag epoch: [headSeqs] aligned to the
  /// projected transcript head, [index] the epoch's file-order snapshot.
  const TranscriptSeqMap({required this.headSeqs, required this.index});

  /// The seqs of the projected head, aligned by message index (`null` =
  /// a non-record). Treated as read-only by every consumer.
  final List<int?> headSeqs;

  /// The epoch's record index (seq → record). Frozen at epoch start: an
  /// id beyond it never resolves, so a mis-predicted live-edge alias
  /// cannot hide someone else's record.
  final RecordSeqIndex index;

  /// Number of head messages (the projected transcript at epoch start).
  int get headLength => headSeqs.length;

  /// The alias of the message at [position]: exact on the head (the
  /// epoch's records), `null` beyond it — the live edge carries no tag
  /// (the epoch rule: a message becomes addressable when the NEXT epoch's
  /// projection makes it a record) — and `null` for a non-record.
  int? seqAt(int position) {
    if (position < 0 || position >= headSeqs.length) return null;
    return headSeqs[position];
  }

  /// The stable record id the alias at [position] resolves to on the
  /// epoch index — `null` for non-records, the live edge and unknown
  /// aliases.
  String? recordIdAt(int position) {
    final seq = seqAt(position);
    if (seq == null) return null;
    final record = index.recordAt(seq);
    return record?.id;
  }

  /// The seqs of a [length]-message transcript, aligned by index.
  List<int?> seqsFor(int length) => [for (var i = 0; i < length; i++) seqAt(i)];
}

/// The tag budget of [taggedRecords] tagged messages (the `tagOverhead`
/// term of the request estimate).
int tagOverheadTokens(int taggedRecords) =>
    taggedRecords <= 0 ? 0 : taggedRecords * recordTagTokens;

/// How many messages in [seqs] are tagged records — all of them without a
/// usage anchor, only the ones AFTER the anchor with one (the anchor's
/// reported usage already priced the tags of everything up to it).
int taggedRecordCount(List<int?> seqs, {int? after}) {
  var count = 0;
  for (var i = 0; i < seqs.length; i++) {
    if (seqs[i] != null && (after == null || i > after)) count++;
  }
  return count;
}

/// Stamps record tags on a COPY of [messages]: every message whose aligned
/// seq is non-null gets `m<seq> ` in its first text block; non-records and
/// a `null` map pass through UNTOUCHED (the untagged transcript, the same
/// list). The transcript itself is never modified (I4).
List<Message> tagTranscript(List<Message> messages, TranscriptSeqMap? seqMap) {
  if (seqMap == null || messages.isEmpty) return messages;
  final tagged = <Message>[];
  var changed = false;
  for (var i = 0; i < messages.length; i++) {
    final seq = seqMap.seqAt(i);
    final message = messages[i];
    if (seq == null || messageHasRecordTag(message)) {
      tagged.add(message);
      continue;
    }
    final copy = tagRecordMessage(message, seq);
    changed = true;
    tagged.add(copy);
  }
  return changed ? tagged : messages;
}

/// [tagTranscript] over a request [Context]: the system prompt and tools
/// ride byte-identically, only the message copies carry tags.
Context tagContext(Context context, TranscriptSeqMap? seqMap) {
  if (seqMap == null) return context;
  final tagged = tagTranscript(context.messages, seqMap);
  if (identical(tagged, context.messages)) return context;
  return Context(
    systemPrompt: context.systemPrompt,
    messages: tagged,
    tools: context.tools,
  );
}

/// The tagged copy of one record [message]: the tag goes into the first
/// text block — for an assistant message, the first text block AFTER its
/// leading thinking blocks (signed thinking keeps its position and
/// order; the tag never lands before it). A record with no text block
/// (a pure tool-call carrier, an image-only record) gets a new first
/// text block holding the tag alone (plus `image/<mime>` for images) —
/// image parts are never touched (E17, E18).
Message tagRecordMessage(Message message, int seq) {
  final tag = recordTag(seq);
  switch (message) {
    case UserMessage(:final content, :final timestamp):
      if (content is String) {
        return UserMessage(
          content: _tagText(content, tag),
          timestamp: timestamp,
        );
      }
      return UserMessage(
        content: _tagBlocks(content as List<ContentBlock>, tag),
        timestamp: timestamp,
      );
    case ToolResultMessage(
      :final toolCallId,
      :final toolName,
      :final content,
      :final isError,
      :final timestamp,
    ):
      return ToolResultMessage(
        toolCallId: toolCallId,
        toolName: toolName,
        content: _tagBlocks(content, tag),
        isError: isError,
        timestamp: timestamp,
      );
    case AssistantMessage(:final content):
      return message.copyWith(content: _tagAssistantBlocks(content, tag));
    default:
      return message;
  }
}

String _tagText(String text, String tag) =>
    hasRecordTag(text) ? text : '$tag $text';

String _tagBlocksText(String text, String tag) => '$tag $text';

List<ContentBlock> _tagBlocks(List<ContentBlock> blocks, String tag) {
  for (var i = 0; i < blocks.length; i++) {
    final block = blocks[i];
    if (block is TextContent) {
      if (hasRecordTag(block.text)) return blocks;
      return [
        for (var j = 0; j < blocks.length; j++)
          if (j == i)
            block.copyWith(text: _tagBlocksText(block.text, tag))
          else
            blocks[j],
      ];
    }
  }
  // No text block: a tag-only block in front (image parts untouched).
  final image = blocks.whereType<ImageContent>().firstOrNull;
  final label = image == null ? tag : '$tag image/${image.mimeType}';
  return [TextContent(text: label), ...blocks];
}

List<ContentBlock> _tagAssistantBlocks(List<ContentBlock> blocks, String tag) {
  var index = 0;
  while (index < blocks.length && blocks[index] is ThinkingContent) {
    index++;
  }
  for (var i = index; i < blocks.length; i++) {
    final block = blocks[i];
    if (block is TextContent) {
      if (hasRecordTag(block.text)) return blocks;
      return [
        for (var j = 0; j < blocks.length; j++)
          if (j == i)
            block.copyWith(text: _tagBlocksText(block.text, tag))
          else
            blocks[j],
      ];
    }
  }
  // Pure tool-call carrier: a tag-only text block after the thinking
  // blocks (never before signed thinking).
  return [...blocks.take(index), TextContent(text: tag), ...blocks.skip(index)];
}

/// `RequestSnapshot` (S0) — the last MAIN request "as sent" (GOAL #2394).
///
/// The hand-over call reads the exact prefix the session just warmed:
/// system prompt, tools and the message list of the last main send, plus
/// the record index the request's `m<seq>` tags resolve against. Every
/// main send overwrites the snapshot (last wins — the degenerate-empty
/// retry streams the same context); a snapshot is INVALID once it no
/// longer describes the live context:
///
/// - the session model changed (`prepareNextTurn` switched models — the
///   prefix a different model cached is nobody's warm bucket);
/// - a compaction run succeeded (the projection changed);
/// - the host switched branches / restored a checkpoint (the projection
///   was replaced — hosts call [RequestSnapshotStore.invalidate]).
///
/// A failed compaction run leaves the snapshot valid (nothing was
/// appended). S0 is a `Context`, not wire bytes: adapters rewrite the
/// payload — byte-identity of the prefix is asserted on the payload the
/// adapter serializes (`onPayload`), for the same model and compat.
///
/// Pure Dart — no IO.
library;

import '../context.dart';
import '../model.dart';
import '../types.dart';
import 'record_tag.dart';

/// How long a snapshot's cache bucket counts as warm (the report's
/// `bucket` signal — never a mode condition): Anthropic ephemeral
/// breakpoints and OpenAI prefix caches live ~5 minutes.
const Duration requestSnapshotBucketTtl = Duration(minutes: 5);

/// Whether [a] and [b] are the same served model (provider + id + base
/// URL) — the identity a snapshot's warm bucket is keyed by.
bool sameServedModel(Model a, Model b) =>
    a.provider == b.provider && a.id == b.id && a.baseUrl == b.baseUrl;

/// The last main request as sent. Immutable; [messages] is a private copy.
final class RequestSnapshot {
  /// Creates a snapshot; [messages] is copied, [seqMap] is the epoch the
  /// request's tags were stamped from.
  RequestSnapshot({
    required this.model,
    required List<Message> messages,
    this.systemPrompt,
    List<Tool> tools = const [],
    required this.seqMap,
    required this.sentAt,
    this.routing,
  }) : messages = List.unmodifiable(messages),
       tools = List.unmodifiable(tools);

  /// The model that served the request (`config.model` at send time —
  /// `prepareNextTurn` may have switched it away from the state model).
  final Model model;

  /// The request messages exactly as sent (post-transform — `time-left:`
  /// lines, pin carriers, pairing repairs included).
  final List<Message> messages;

  /// The request's system prompt.
  final String? systemPrompt;

  /// The request's tool manifest.
  final List<Tool> tools;

  /// The tag epoch the request was stamped from: seq → record resolution
  /// for the hand-over reply's hide list happens against THIS frozen
  /// index, never a fresh ledger (aliases drift under windowed storage
  /// and hard caps; the live edge — untaged — never names an alias).
  final TranscriptSeqMap seqMap;

  /// When the request was handed to the provider stream.
  final DateTime sentAt;

  /// The routing values the request rode (zone overrides), when any.
  final RequestRouting? routing;

  /// Whether this snapshot still describes the context [current] would
  /// send next: same served model.
  bool isValidFor(Model current) => sameServedModel(model, current);

  /// `warm` while the provider cache bucket the request wrote is still
  /// alive ([requestSnapshotBucketTtl]), else `cold` — a report signal.
  String bucket({DateTime? now}) =>
      (now ?? DateTime.now()).difference(sentAt) <= requestSnapshotBucketTtl
      ? 'warm'
      : 'cold';

  /// The stable record id behind alias [seq] on the frozen epoch index —
  /// `null` for unknown aliases (beyond the index, non-positive) and for
  /// records that never project into the model context (the hidden-range
  /// and pin bookkeeping records themselves).
  String? recordIdAt(int seq) {
    if (seq <= 0) return null;
    final record = seqMap.index.recordAt(seq);
    return record?.id;
  }

  /// The snapshot as the request context the hand-over call extends: a
  /// fresh `Context` over the stored copies (callers append their
  /// instruction to a COPY of the list).
  Context toContext({List<Message> extraMessages = const []}) => Context(
    systemPrompt: systemPrompt,
    messages: [...messages, ...extraMessages],
    tools: tools.isEmpty ? null : tools,
  );

  /// The prefix message count — the history breakpoint position the
  /// hand-over call passes to adapters that support `prefixLength` (the
  /// breakpoint sits on S0's last message, not on the instruction).
  int get prefixLength => messages.length;
}

/// The routing values a request rode.
final class RequestRouting {
  /// Creates the routing record.
  const RequestRouting({this.sessionId, this.cacheRetention});

  /// The prompt-cache affinity id (null = the provider default resolved
  /// at call time).
  final String? sessionId;

  /// The cache retention (`short`/`long`/`none`; null = provider default).
  final String? cacheRetention;
}

/// Last-wins holder of the session's [RequestSnapshot] — ONE per agent,
/// written at the main-send seam, read by the compaction host.
final class RequestSnapshotStore {
  RequestSnapshot? _snapshot;
  String? _invalidReason;

  /// The current snapshot, valid or not (hosts render its state).
  RequestSnapshot? get current => _snapshot;

  /// Why the last snapshot was invalidated, when a host/compaction run
  /// did it explicitly (model switches report through [validFor]).
  String? get invalidReason => _invalidReason;

  /// Records the latest main send (last wins, clears any invalidation).
  void capture(RequestSnapshot snapshot) {
    _snapshot = snapshot;
    _invalidReason = null;
  }

  /// Drops the snapshot — the projection it described is gone.
  void invalidate(String reason) {
    _snapshot = null;
    _invalidReason = reason;
  }

  /// The snapshot when it is still valid for [model], else `null`.
  RequestSnapshot? validFor(Model model) {
    final snapshot = _snapshot;
    if (snapshot == null || snapshot.isValidFor(model)) return snapshot;
    return null;
  }
}

