) {
  if (!_userIntentHeading.hasMatch(text)) return text;
  final lines = text.split('\n');
  final out = <String>[];
  final pin = _BeltPinEnvelope();
  var i = 0;
  while (i < lines.length) {
    final line = lines[i];
    final trimmed = line.trim();
    if (pin.entersKept(trimmed)) {
      out.add(line);
      pin.completeKept(trimmed);
      i++;
      continue;
    }
    if (!_userIntentHeading.hasMatch(trimmed)) {
      out.add(line);
      i++;
      continue;
    }
    out.add(line);
    final (belted, end) = _beltSectionBody(
      lines,
      start: i + 1,
      sectionHeaded: _mdHeading.hasMatch(line),
      origins: origins,
      protectedLines: protectedLines,
      stripped: stripped,
      marked: marked,
      pin: pin,
    );
    out.addAll(belted);
    i = end;
  }
  return out.join('\n');
}

/// The belt walk's pin-envelope exemption state (the gh-1409 envelope
/// semantics, bound to the belt's line walk): an open envelope keeps its
/// lines verbatim until the close tag or the bounded re-arm (defense in
/// depth against a hostile unclosed open), exactly mirroring the
/// `sanitizeSummary` line loop's counter placement — the open decision
/// precedes the kept test on every line, and the counter/close bookkeeping
/// rides ONLY the kept (pasthrough) branch, never the graded path.
final class _BeltPinEnvelope {
  bool _open = false;
  int _count = 0;

  /// Opens the envelope on an open tag, then tests the exemption.
  bool entersKept(String trimmed) {
    if (trimmed == pinEnvelopeOpenTag) {
      _open = true;
      _count = 0;
    }
    return _open && _count < _maxPinEnvelopeLines;
  }

  /// Pasthrough-path bookkeeping only: the line counter and the close tag
  /// are processed for kept lines. A graded or boundary line inside a
  /// re-armed envelope can neither extend nor close the exemption — the
  /// same sequencing as the `sanitizeSummary` loop.
  void completeKept(String trimmed) {
    if (_open) _count++;
    if (trimmed == pinEnvelopeCloseTag) _open = false;
  }
}

/// Consumes one user-intent section body — every line after its heading
/// until the section ends (a markdown heading or `covers:` line, or body
/// prose after a bare `open asks:` heading) or the transcript ends — and
/// returns the belted lines plus the index the caller must resume at (the
/// boundary line itself, so it is reprocessed from the outside state).
/// Pin-envelope lines ([_BeltPinEnvelope.entersKept]) are kept verbatim;
/// an envelope open when the heading arrives keeps the heading in the
/// walker's pasthrough branch, so no section opens and nothing is graded
/// until the envelope closes or re-arms.
(List<String>, int) _beltSectionBody(
  List<String> lines, {
  required int start,
  required bool sectionHeaded,
  required SummaryOriginEvidence? origins,
  required Set<String> protectedLines,
  required List<String> stripped,
  required List<String> marked,
  required _BeltPinEnvelope pin,
}) {
  final out = <String>[];
  var i = start;
  while (i < lines.length) {
    final line = lines[i];
    final trimmed = line.trim();
    if (pin.entersKept(trimmed)) {
      out.add(line);
      pin.completeKept(trimmed);
      i++;
      continue;
    }
    if (_isSectionEnd(line, trimmed)) break;
    if (trimmed.isEmpty) {
      out.add(line);
      i++;
      continue;
    }
    final bullet = _bulletMarker.hasMatch(line);
    if (!bullet && _endsBareHeadingSection(line, sectionHeaded)) break;
    final end = bullet ? _bulletBlockEnd(lines, i) : i + 1;
    final block = lines.sublist(i, end);
    final verdict = _beltVerdict(block, origins, protectedLines, stripped);
    out.addAll(_applyBeltVerdict(verdict, block, marked));
    i = end;
  }
  return (out, i);
}

/// Whether [line] ends the section it is walking inside: any markdown
/// heading, or a `covers:` line (the next fold's coverage marker).
bool _isSectionEnd(String line, String trimmed) =>
    _mdHeading.hasMatch(line) || _coversLine.hasMatch(trimmed);

/// Whether a non-bullet [line] ends a bare `open asks:` section: body prose
/// at column 0 under an unmarked heading — the checkpoint's post-asks
/// narrative — is outside the asks list.
bool _endsBareHeadingSection(String line, bool sectionHeaded) =>
    !sectionHeaded && !line.startsWith(_leadingWhitespace);

/// Where a bullet block starting at [start] ends: the bullet plus its
/// indented, non-empty, non-bullet continuation lines ride one verdict.
int _bulletBlockEnd(List<String> lines, int start) {
  var end = start + 1;
  while (end < lines.length &&
      lines[end].trim().isNotEmpty &&
      lines[end].startsWith(_leadingWhitespace) &&
      !_bulletMarker.hasMatch(lines[end])) {
    end++;
  }
  return end;
}

/// Belt verdicts for one content block.
enum _BeltVerdict {
  /// No laundering signal — the block survives byte-identical.
  keep,

  /// Machine-origin content in a user-intent section — the block drops.
  strip,

  /// Tool-verbatim quote posing as user intent — the block gains an
  /// origin mark.
  mark,
}

/// Grades one bullet block (or prose line) of a user-intent section.
_BeltVerdict _beltVerdict(
  List<String> block,
  SummaryOriginEvidence? origins,
  Set<String> protectedLines,
  List<String> stripped,
) {
  for (final line in block) {
    for (final protected in protectedLines) {
      if (protected.isNotEmpty && line.contains(protected)) {
        return _BeltVerdict.keep; // gh-1409: pins are never rewritten.
      }
    }
  }
  var content = block.join(' ').replaceFirst(_bulletContentPrefix, '');
  final flat = _flattenText(content);
  if (flat.isEmpty) return _BeltVerdict.keep;
  // Arm 1 — machine-origin BY CONSTRUCTION: the request-candidate scan
  // already refuses these classes at the source, so their presence in a
  // user-intent section is laundering whatever phrasing wraps them.
  if (isSyntheticUserText(flat)) {
    stripped.add(flat);
    return _BeltVerdict.strip;
  }
  // Arm 2 — tool-verbatim quote (needs the fold's transcript evidence).
  if (origins != null && _quotesToolText(flat, origins)) {
    return _BeltVerdict.mark;
  }
  return _BeltVerdict.keep;
}

/// Whether [flatContent] in a user-intent section verbatim-quotes a tool
/// result without quoting the user: the whole content is user-sourced
/// (either containment direction — digests append scaffolding like
/// `(asked <date>, id)` around verbatim asks), or it carries a
/// [_minQuoteChars]-char sentence found inside a tool text and inside no
/// user text. The sentence grading lives in [_launderedQuoteSentence].
bool _quotesToolText(String flatContent, SummaryOriginEvidence origins) {
  if (flatContent.length < _minQuoteChars) return false;
  if (_containedInAny(origins.userTexts, flatContent, alsoContains: true)) {
    return false;
  }
  return flatContent
      .split(_sentenceSplit)
      .any((sentence) => _launderedQuoteSentence(sentence, origins));
}

/// Whether one sentence of a user-intent line is a laundering quote: long
/// enough to be distinctive, verbatim inside a tool result, and inside no
/// user text. Digest scaffolding rides the line — a candidate pointer
/// (`[r7 · …]`) prefixed to a verbatim quote must not hide the quote — so
/// the sentence is retried without its leading bracket groups.
bool _launderedQuoteSentence(String sentence, SummaryOriginEvidence origins) {
  if (sentence.length < _minQuoteChars) return false;
  if (_containedInAny(origins.userTexts, sentence)) return false;
  if (_containedInAny(origins.toolTexts, sentence)) return true;
  final bare = sentence.replaceFirst(_leadingBrackets, '');
  if (bare.length < _minQuoteChars || bare == sentence) return false;
  return _containedInAny(origins.toolTexts, bare);
}

/// Whether [needle] occurs verbatim inside any of [texts]; [alsoContains]
/// adds the reverse containment (the needle contains the text) — the
/// digest-scaffolding case where a real ask line wraps its own user text.
bool _containedInAny(
  List<String> texts,
  String needle, {
  bool alsoContains = false,
}) {
  for (final text in texts) {
    if (text.contains(needle) || (alsoContains && needle.contains(text))) {
      return true;
    }
  }
  return false;
}

/// Applies a [_BeltVerdict]: `keep` returns the block unchanged, `strip`
/// drops it (the fires were already logged by [_beltVerdict]), `mark`
/// appends the origin mark to the block's first line and logs the annotated
/// line in [marked].
List<String> _applyBeltVerdict(
  _BeltVerdict verdict,
  List<String> block,
  List<String> marked,
) {
  switch (verdict) {
    case _BeltVerdict.keep:
      return block;
    case _BeltVerdict.strip:
      return const [];
    case _BeltVerdict.mark:
      final annotated = '${block.first} [from toolResult]';
      marked.add(annotated);
      return [annotated, ...block.skip(1)];
  }
}

/// The pin-envelope exemption's line bound (defense in depth): a
/// budget-capped legit pin block is ≤ ~273 rendered lines at
/// [defaultPinBudgetChars] (8192 chars over the ~30-char minimal
/// rendering), so 512 is provably above any legit block while a hostile
/// unclosed open cannot latch the exemption over the whole summary.
const _maxPinEnvelopeLines = 512;

/// Aliases of the renderer's envelope tags — single source of truth in
/// `structured/markers.dart` ([pinBlockOpenTag]/[pinBlockCloseTag]);
/// compile-time linked, so a renderer rename cannot silently orphan the
/// exemption (review gh-1409 round 2, suggestion 5).
const pinEnvelopeOpenTag = pinBlockOpenTag;
const pinEnvelopeCloseTag = pinBlockCloseTag;

/// Removes every `[context note …]` block — opened by a real bracket and
/// closed by a `]` within the same line or the two lines after it (LLM
/// summaries reflow notes at ~80 columns); an unterminated or far-closed
/// opener is prose that merely mentions a context note and is left
/// untouched. Removed spans are recorded as stripped.
String _stripContextNotes(String text, List<String> stripped) {
  final out = StringBuffer();
  var start = 0;
  for (final match in _contextNoteOpen.allMatches(text)) {
    if (match.start < start) continue; // opener inside a removed block
    final close = text.indexOf(']', match.end);
    final searchEnd = close < 0 ? text.length : close;
    final newlines = '\n'
        .allMatches(text.substring(match.end, searchEnd))
        .length;
    if (close < 0 || newlines > 2) continue;
    out.write(text.substring(start, match.start));
    var end = close + 1;
    // A note occupying a whole line takes its line break with it, so the
    // strip does not leave a blank line behind.
    if (end < text.length &&
        text[end] == '\n' &&
        (match.start == 0 || text[match.start - 1] == '\n')) {
      end++;
    }
    final removed = text.substring(match.start, end);
    if (removed.trim().isNotEmpty) stripped.add(removed.trim());
    start = end;
  }
  out.write(text.substring(start));
  return out.toString();
}

/// Strips ephemeral sentences from one [line]; `null` when nothing survives
/// (the line carried only ephemeral content and is dropped whole). A line
/// containing any of [protectedLines] verbatim (gh-1409 AC4: pinned skill
/// directives) is returned unchanged.
String? _sanitizeLine(
  String line,
  List<String> stripped,
  Set<String> protectedLines,
) {
  final pinKept = _pinProtectedLine(line, protectedLines);
  if (pinKept != null) return pinKept;
  final sentences = line.split(RegExp(r'(?<=[.!?])\s+'));
  final kept = _stripEphemeralSentences(sentences, stripped);
  if (kept == null) return line; // nothing stripped → byte-identical.
  if (kept.isEmpty) return null; // the line carried only ephemeral text.
  return _reassembleStrippedLine(line, kept.join(' '));
}

/// The gh-1409 AC4 guard: [line] survives verbatim when it contains any of
/// [protectedLines] (a pin carrying the summary must not be mangled by the
/// ephemeral-claim strips around it). `null` → not protected.
String? _pinProtectedLine(String line, Set<String> protectedLines) {
  for (final protected in protectedLines) {
    if (protected.isNotEmpty && line.contains(protected)) return line;
  }
  return null;
}

/// Drops the ephemeral-claim sentences ([_secondPerson] + [_ephemeralClaim])
/// from [sentences], recording each in [stripped]. `null` → nothing was
/// ephemeral (the caller keeps the line byte-identical).
List<String>? _stripEphemeralSentences(
  List<String> sentences,
  List<String> stripped,
) {
  final kept = <String>[];
  var removed = 0;
  for (final sentence in sentences) {
    if (_secondPerson.hasMatch(sentence) &&
        _ephemeralClaim.hasMatch(sentence)) {
      if (sentence.trim().isNotEmpty) stripped.add(sentence.trim());
      removed++;
      continue;
    }
    kept.add(sentence);
  }
  if (removed == 0) return null;
  return kept;
}

/// Reassembles a line whose ephemeral sentences were stripped: a bare
/// surviving list marker ("2." after its content was stripped) is noise
/// (`null` — the line drops), and a partially stripped bullet keeps its
/// marker so the list stays valid.
String? _reassembleStrippedLine(String line, String text) {
  if (RegExp(r'^\s*(?:[-*+]|\d+\.)$').hasMatch(text)) return null;
  final bullet = RegExp(r'^(\s*(?:[-*+]|\d+\.)\s+)');
  if (bullet.hasMatch(line) && !bullet.hasMatch(text)) {
    return bullet.firstMatch(line)!.group(1)! + text.trimLeft();
  }
  return text;
}

/// Time-scoped claim sanitizer for compaction summaries (issue #1131).
///
/// A compaction summary is a durable fact sheet re-rendered into the model
/// context on every later turn. An ephemeral observation written at fold
/// time — "your LAST tool call's RESULT was dropped from context" — therefore
/// re-renders forever as a current fact: the claim was true once (a harness
/// context note about a real one-shot drop) but persists as standing prose
/// the model re-verifies every turn. The summarizer prompts forbid such
/// claims (see `prompts/compaction/*.md`); this sanitizer is the belt next
/// to that suspender — ephemeral sentences are stripped before a summary is
/// persisted or projected into context, so pre-existing poisoned summaries
/// heal on read too (session JSONL stays untouched).
///
/// The pattern is deliberately narrow — a bracketed `[context note …]` /
/// `[CONTEXT NOTE — …]` block, or a sentence addressing the reader in the
/// second person WHILE claiming recency or a drop — so durable uses of
/// temporal words survive: "the last release was v1.0.492", "the current
/// maintainer is X", and quoted history like "the user asked you to re-run
/// the tests" all stay verbatim.
///
/// gh-2103 adds the provenance belt over the same chokepoints: digest text
/// must not launder tool-controlled content into trusted memory. Within the
/// user-intent sections of a digest (`## Open User Requests`, `## Original
/// Request`, `open asks:`), machine-origin lines (the [isSyntheticUserText]
/// classes — the same lines the request-candidate scan refuses to feed the
/// summarizer) are stripped, and a line quoting tool text verbatim carries
/// a `[from toolResult]` origin mark. The mark arm grades against
/// [SummaryOriginEvidence] — the transcript the fold consumed — so it is
/// wired at persist sites; heal-on-read sites pass no evidence and only the
/// synthetic arm fires.
library;

import '../context.dart' show ToolResultMessage, UserMessage;
import '../types.dart' show Message, TextContent;
import '../user_text.dart' show isSyntheticUserText, userMessageText;
import 'structured/markers.dart' show pinBlockCloseTag, pinBlockOpenTag;

/// A summary after sanitization: the cleaned [text] plus the [stripped]
/// ephemeral/laundered spans (persist sites log them, e.g. in the compaction
/// record's `details`) and the [marked] lines that gained a `[from
/// toolResult]` origin mark (gh-2103, logged alongside the strips).
typedef SanitizedSummary = ({
  String text,
  List<String> stripped,
  List<String> marked,
});

/// Flattened transcript-origin evidence for the provenance belt (gh-2103).
///
/// Built at persist sites from the same [messages] the summarizer consumed:
/// the whitespace-flattened text of every user message and every tool
/// result of the summarized span. A digest line in a user-intent section
/// that verbatim-quotes one of the tool texts (and no user text) is a
/// laundered quote — the belt origin-marks it; a line contained in (or
/// containing) a user text is user-sourced and stays untouched.
final class SummaryOriginEvidence {
  /// Collects the origin evidence of one summarized span.
  SummaryOriginEvidence(Iterable<Message> messages)
    : userTexts = [
        for (final message in messages)
          if (message is UserMessage)
            if (_flattenText(userMessageText(message.content)).isNotEmpty)
              _flattenText(userMessageText(message.content)),
      ],
      toolTexts = [
        for (final message in messages)
          if (message is ToolResultMessage)
            if (_flattenText(
              message.content
                  .whereType<TextContent>()
                  .map((block) => block.text)
                  .join('\n'),
            ).isNotEmpty)
              _flattenText(
                message.content
                    .whereType<TextContent>()
                    .map((block) => block.text)
                    .join('\n'),
              ),
      ];

  /// Flattened user-message texts of the span.
  final List<String> userTexts;

  /// Flattened tool-result texts of the span.
  final List<String> toolTexts;
}

final RegExp _contextNoteOpen = RegExp(
  r'\[\s*context notes?\s*[—–\-:]',
  caseSensitive: false,
);

final RegExp _secondPerson = RegExp(
  r'\b(?:you|your|yours|yourself)\b',
  caseSensitive: false,
);

/// The ephemeral constructions themselves — adjacency, not co-occurrence.
/// A bare second-person pronoun plus a bare temporal word anywhere in a
/// sentence strips durable prose ("the user asked you to re-run the full
/// suite after the previous fix lands"); only these claim shapes fire.
///
/// - The possessive arm additionally demands a loss/trim verb in the same
///   sentence: "rebase your previous commits" is a constraint, not a drop
///   claim; "your last tool call's result was dropped" is the claim.
/// - The `you`-arm covers contracted and interpolated forms ("you've
///   just", "you're about to", "you were (just) about to"). A bare "you
///   just" additionally demands a following PAST-TENSE verb form:
///   regular verbs ending in -ed (minus present-tense verbs that merely
///   end in -ed) or a common irregular. English irregular pasts are a
///   finite closed set, so the irregular alternation is exhaustive for
///   the verbs summaries use - except the homographs whose past spelling
///   equals their present (hit, cut, set, put, read): matching those
///   would also strip present-tense habituals, so they are the
///   deliberate floor. "you just merged the PR" is a recency claim,
///   while "you just need to re-run make", "if you just look at the
///   failing test", and reported speech ("you just said" / "you
///   just told me") are durable and survive.
final RegExp _ephemeralClaim = RegExp(
  r"\byour\s+(?:last|previous|prior)\b"
  r"(?=[^.]*\b(?:dropped|trimmed|removed|lost)\b)"
  r"|\byou(?:'ve\s+just|'re\s+about to|\s+(?:were\s+)?(?:just\s+)?about to"
  r"|\s+just(?=\s+(?:(?!(?:need|seed|embed|speed|proceed|exceed|succeed)\b)\w+ed"
  r"|(?:ran|did|went|got|saw|wrote|made|found|broke|sent|took|left|came|gave"
  r"|built|lost|kept|held|felt|spent|brought|heard|met|paid|won"
  r"|began|forgot|sold|fell|rose|flew|grew|threw|drove|spoke|chose|stood))\b))\b"
  r'|\b(?:was|were)\s+dropped\b',
  caseSensitive: false,
);

/// Strips ephemeral, time-scoped claims from a compaction [summary], and —
/// gh-2103 — belts the user-intent sections against laundering when the
/// fold's transcript [origins] is given (a `null` [origins], the heal-on-read
/// shape, still strips machine-origin lines; it just cannot grade quotes).
///
/// Whole `[context note …]` blocks go first (the harness delivers drop notes
/// itself, once, at the turn where they happen — a copy inside a summary is
/// always the stale-re-render class). Then any sentence that both addresses
/// the reader in the second person and claims recency or a drop is removed.
/// Everything else survives byte-identical.
///
/// gh-1409 pin exemption (AC4/F6): a sentence containing any of
/// [protectedLines] verbatim is never stripped or rewritten — these are
/// compaction-pinned skill directives riding the summary, and the
/// sanitizer must not mangle them while stripping ephemeral claims around
/// them. Lines inside a `<pinned-skill-directives>` envelope are
/// structurally exempt too (the pin block framing is harness-generated),
/// which protects pins in summaries healed on the projection path, where
/// the pin set is not known.
SanitizedSummary sanitizeSummary(
  String summary, {
  Set<String> protectedLines = const {},
  SummaryOriginEvidence? origins,
}) {
  if (summary.isEmpty) {
    return (text: summary, stripped: const [], marked: const []);
  }
  final stripped = <String>[];
  final marked = <String>[];
  final text = _stripContextNotes(summary, stripped);
  // gh-2103: user-intent sections never carry machine-origin asks, and
  // tool-verbatim quotes there carry an origin mark. Runs before the
  // ephemeral-claim walk so the per-line strips see the belted text.
  final belted = _beltUserIntentSections(
    text,
    stripped,
    marked,
    origins,
    protectedLines,
  );
  final keptLines = <String>[];
  var insidePinEnvelope = false;
  var envelopeLines = 0;
  for (final line in belted.split('\n')) {
    // Standalone-line equality only (review gh-1409 round 2): the harness
    // renders the tags as whole lines, so a tag quoted mid-prose — a pin
    // line copied into a sentence, or a hostile `operative:` line
    // smuggling the marker — must not flip the exemption.
    final trimmed = line.trim();
    if (trimmed == pinEnvelopeOpenTag) {
      insidePinEnvelope = true;
      envelopeLines = 0;
    }
    // The exemption is BOUNDED: a legit pin block is budget-capped
    // ([defaultPinBudgetChars] ⇒ ≤ ~273 rendered lines), so an unclosed
    // envelope (truncated checkpoint, hostile open without close) re-arms
    // sanitization after [_maxPinEnvelopeLines] lines instead of staying
    // exempt for the rest of the summary.
    final keptLine = insidePinEnvelope && envelopeLines < _maxPinEnvelopeLines
        ? line
        : _sanitizeLine(line, stripped, protectedLines);
    if (keptLine != null) keptLines.add(keptLine);
    if (insidePinEnvelope) envelopeLines++;
    if (trimmed == pinEnvelopeCloseTag) insidePinEnvelope = false;
  }
  return (text: keptLines.join('\n'), stripped: stripped, marked: marked);
}

// ---------------------------------------------------------------------------
// The provenance belt (gh-2103) — no laundering through user-intent sections
// ---------------------------------------------------------------------------

/// Headings whose digest sections claim USER INTENT: the classic
/// checkpoint's `## Open User Requests`, the split-turn prefix's
/// `## Original Request`, and the structured checkpoint's bare
/// `open asks:` heading. Only inside these sections can text pose AS the
/// user; everywhere else tool-derived quotes are legitimate context.
final RegExp _userIntentHeading = RegExp(
  r'^(?:#{1,6}\s+)?(?:open user requests\b|original request\b|open asks\b\s*:)',
  caseSensitive: false,
  multiLine: true,
);

final RegExp _mdHeading = RegExp(r'^#{1,6}\s');

final RegExp _bulletMarker = RegExp(r'^\s*(?:[-*+]\s|\d+\.\s)');

/// List marker plus optional task checkbox, stripped when the belt reads a
/// bullet's content.
final RegExp _bulletContentPrefix = RegExp(
  r'^\s*(?:[-*+]\s|\d+\.\s)\s*(?:\[[ xX]\]\s*)?',
);

final RegExp _coversLine = RegExp(r'^covers\b\s*:', caseSensitive: false);

/// Minimum verbatim-quote length the mark arm requires: shorter strings
/// ("error: file not found", a command name) collide too easily between a
/// real ask and incidental tool output, so they never fire the arm.
const _minQuoteChars = 24;

final RegExp _sentenceSplit = RegExp(r'(?<=[.!?])\s+');

/// Leading candidate-pointer bracket groups (`[r7 · 2026-11-14] `) the belt
/// strips before retrying a sentence against the tool bodies.
final RegExp _leadingBrackets = RegExp(r'^(?:\[[^\]]*\]\s*)+');

final RegExp _whitespaceRun = RegExp(r'\s+');

/// Leading whitespace test for the belt walk's continuation/bare-prose
/// classification (`_bulletBlockEnd`, `_endsBareHeadingSection`).
final RegExp _leadingWhitespace = RegExp(r'\s');

String _flattenText(String text) => text.replaceAll(_whitespaceRun, ' ').trim();

/// The gh-2103 belt over the user-intent sections of [text].
///
/// Within a section (from a [_userIntentHeading] line to the next markdown
/// heading, a `covers:` line, or — for the bare `open asks:` shape — the
/// first unindented prose line):
///
/// - a line (bullet block, or a prose line under a `#`-headed section)
///   whose flattened content is machine-origin by construction
///   ([isSyntheticUserText] — the same predicate the request-candidate scan
///   applies at the source) is STRIPPED and logged in [stripped];
/// - when [origins] is present and the content is user-sourced by neither
///   whole-content nor per-sentence verbatim containment, but a ≥
///   [_minQuoteChars]-char sentence IS verbatim inside a tool result, the
///   line is annotated with ` [from toolResult]` and logged in [marked].
///
/// Everything else — real asks above all — survives byte-identical. Pinned
/// directives ([protectedLines]) and the `<pinned-skill-directives>`
/// envelope are exempt, exactly as for the ephemeral-claim strips.
///
/// The walk is split so each decision stays under the CRAP ratchet: this
/// walker only dispatches whole sections to [_beltSectionBody] (pin
/// envelope lines via [_BeltPinEnvelope]); the section body grades bullet
/// blocks and prose lines and reports where the section ended.
String _beltUserIntentSections(
  String text,
  List<String> stripped,
  List<String> marked,
  SummaryOriginEvidence? origins,
  Set<String> protectedLines,
) {
  if (!_userIntentHeading.hasMatch(text)) return text;
  final lines = text.split('\n');
  final out = <String>[];
  final pin = _BeltPinEnvelope();
  var i = 0;
  while (i < lines.length) {
    final line = lines[i];
    final trimmed = line.trim();
    if (pin.entersKept(trimmed)) {
      out.add(line);
      pin.completeKept(trimmed);
      i++;
      continue;
    }
    if (!_userIntentHeading.hasMatch(trimmed)) {
      out.add(line);
      i++;
      continue;
    }
    out.add(line);
    final (belted, end) = _beltSectionBody(
      lines,
      start: i + 1,
      sectionHeaded: _mdHeading.hasMatch(line),
      origins: origins,
      protectedLines: protectedLines,
      stripped: stripped,
      marked: marked,
      pin: pin,
    );
    out.addAll(belted);
    i = end;
  }
  return out.join('\n');
}

/// The belt walk's pin-envelope exemption state (the gh-1409 envelope
/// semantics, bound to the belt's line walk): an open envelope keeps its
/// lines verbatim until the close tag or the bounded re-arm (defense in
/// depth against a hostile unclosed open), exactly mirroring the
/// `sanitizeSummary` line loop's counter placement — the open decision
/// precedes the kept test on every line, and the counter/close bookkeeping
/// rides ONLY the kept (pasthrough) branch, never the graded path.
final class _BeltPinEnvelope {
  bool _open = false;
  int _count = 0;

  /// Opens the envelope on an open tag, then tests the exemption.
  bool entersKept(String trimmed) {
    if (trimmed == pinEnvelopeOpenTag) {
      _open = true;
      _count = 0;
    }
    return _open && _count < _maxPinEnvelopeLines;
  }

  /// Pasthrough-path bookkeeping only: the line counter and the close tag
  /// are processed for kept lines. A graded or boundary line inside a
  /// re-armed envelope can neither extend nor close the exemption — the
  /// same sequencing as the `sanitizeSummary` loop.
  void completeKept(String trimmed) {
    if (_open) _count++;
    if (trimmed == pinEnvelopeCloseTag) _open = false;
  }
}

/// Consumes one user-intent section body — every line after its heading
/// until the section ends (a markdown heading or `covers:` line, or body
/// prose after a bare `open asks:` heading) or the transcript ends — and
/// returns the belted lines plus the index the caller must resume at (the
/// boundary line itself, so it is reprocessed from the outside state).
/// Pin-envelope lines ([_BeltPinEnvelope.entersKept]) are kept verbatim;
/// an envelope open when the heading arrives keeps the heading in the
/// walker's pasthrough branch, so no section opens and nothing is graded
/// until the envelope closes or re-arms.
(List<String>, int) _beltSectionBody(
  List<String> lines, {
  required int start,
  required bool sectionHeaded,
  required SummaryOriginEvidence? origins,
  required Set<String> protectedLines,
  required List<String> stripped,
  required List<String> marked,
  required _BeltPinEnvelope pin,
}) {
  final out = <String>[];
  var i = start;
  while (i < lines.length) {
    final line = lines[i];
    final trimmed = line.trim();
    if (pin.entersKept(trimmed)) {
      out.add(line);
      pin.completeKept(trimmed);
      i++;
      continue;
    }
    if (_isSectionEnd(line, trimmed)) break;
    if (trimmed.isEmpty) {
      out.add(line);
      i++;
      continue;
    }
    final bullet = _bulletMarker.hasMatch(line);
    if (!bullet && _endsBareHeadingSection(line, sectionHeaded)) break;
    final end = bullet ? _bulletBlockEnd(lines, i) : i + 1;
    final block = lines.sublist(i, end);
    final verdict = _beltVerdict(block, origins, protectedLines, stripped);
    out.addAll(_applyBeltVerdict(verdict, block, marked));
    i = end;
  }
  return (out, i);
}

/// Whether [line] ends the section it is walking inside: any markdown
/// heading, or a `covers:` line (the next fold's coverage marker).
bool _isSectionEnd(String line, String trimmed) =>
    _mdHeading.hasMatch(line) || _coversLine.hasMatch(trimmed);

/// Whether a non-bullet [line] ends a bare `open asks:` section: body prose
/// at column 0 under an unmarked heading — the checkpoint's post-asks
/// narrative — is outside the asks list.
bool _endsBareHeadingSection(String line, bool sectionHeaded) =>
    !sectionHeaded && !line.startsWith(_leadingWhitespace);

/// Where a bullet block starting at [start] ends: the bullet plus its
/// indented, non-empty, non-bullet continuation lines ride one verdict.
int _bulletBlockEnd(List<String> lines, int start) {
  var end = start + 1;
  while (end < lines.length &&
      lines[end].trim().isNotEmpty &&
      lines[end].startsWith(_leadingWhitespace) &&
      !_bulletMarker.hasMatch(lines[end])) {
    end++;
  }
  return end;
}

/// Belt verdicts for one content block.
enum _BeltVerdict {
  /// No laundering signal — the block survives byte-identical.
  keep,

  /// Machine-origin content in a user-intent section — the block drops.
  strip,

  /// Tool-verbatim quote posing as user intent — the block gains an
  /// origin mark.
  mark,
}

/// Grades one bullet block (or prose line) of a user-intent section.
_BeltVerdict _beltVerdict(
  List<String> block,
  SummaryOriginEvidence? origins,
  Set<String> protectedLines,
  List<String> stripped,
) {
  for (final line in block) {
    for (final protected in protectedLines) {
      if (protected.isNotEmpty && line.contains(protected)) {
        return _BeltVerdict.keep; // gh-1409: pins are never rewritten.
      }
    }
  }
  var content = block.join(' ').replaceFirst(_bulletContentPrefix, '');
  final flat = _flattenText(content);
  if (flat.isEmpty) return _BeltVerdict.keep;
  // Arm 1 — machine-origin BY CONSTRUCTION: the request-candidate scan
  // already refuses these classes at the source, so their presence in a
  // user-intent section is laundering whatever phrasing wraps them.
  if (isSyntheticUserText(flat)) {
    stripped.add(flat);
    return _BeltVerdict.strip;
  }
  // Arm 2 — tool-verbatim quote (needs the fold's transcript evidence).
  if (origins != null && _quotesToolText(flat, origins)) {
    return _BeltVerdict.mark;
  }
  return _BeltVerdict.keep;
}

/// Whether [flatContent] in a user-intent section verbatim-quotes a tool
/// result without quoting the user: the whole content is user-sourced
/// (either containment direction — digests append scaffolding like
/// `(asked <date>, id)` around verbatim asks), or it carries a
/// [_minQuoteChars]-char sentence found inside a tool text and inside no
/// user text. The sentence grading lives in [_launderedQuoteSentence].
bool _quotesToolText(String flatContent, SummaryOriginEvidence origins) {
  if (flatContent.length < _minQuoteChars) return false;
  if (_containedInAny(origins.userTexts, flatContent, alsoContains: true)) {
    return false;
  }
  return flatContent
      .split(_sentenceSplit)
      .any((sentence) => _launderedQuoteSentence(sentence, origins));
}

/// Whether one sentence of a user-intent line is a laundering quote: long
/// enough to be distinctive, verbatim inside a tool result, and inside no
/// user text. Digest scaffolding rides the line — a candidate pointer
/// (`[r7 · …]`) prefixed to a verbatim quote must not hide the quote — so
/// the sentence is retried without its leading bracket groups.
bool _launderedQuoteSentence(String sentence, SummaryOriginEvidence origins) {
  if (sentence.length < _minQuoteChars) return false;
  if (_containedInAny(origins.userTexts, sentence)) return false;
  if (_containedInAny(origins.toolTexts, sentence)) return true;
  final bare = sentence.replaceFirst(_leadingBrackets, '');
  if (bare.length < _minQuoteChars || bare == sentence) return false;
  return _containedInAny(origins.toolTexts, bare);
}

/// Whether [needle] occurs verbatim inside any of [texts]; [alsoContains]
/// adds the reverse containment (the needle contains the text) — the
/// digest-scaffolding case where a real ask line wraps its own user text.
bool _containedInAny(
  List<String> texts,
  String needle, {
  bool alsoContains = false,
}) {
  for (final text in texts) {
    if (text.contains(needle) || (alsoContains && needle.contains(text))) {
      return true;
    }
  }
  return false;
}

/// Applies a [_BeltVerdict]: `keep` returns the block unchanged, `strip`
/// drops it (the fires were already logged by [_beltVerdict]), `mark`
/// appends the origin mark to the block's first line and logs the annotated
/// line in [marked].
List<String> _applyBeltVerdict(
  _BeltVerdict verdict,
  List<String> block,
  List<String> marked,
) {
  switch (verdict) {
    case _BeltVerdict.keep:
      return block;
    case _BeltVerdict.strip:
      return const [];
    case _BeltVerdict.mark:
      final annotated = '${block.first} [from toolResult]';
      marked.add(annotated);
      return [annotated, ...block.skip(1)];
  }
}

/// The pin-envelope exemption's line bound (defense in depth): a
/// budget-capped legit pin block is ≤ ~273 rendered lines at
/// [defaultPinBudgetChars] (8192 chars over the ~30-char minimal
/// rendering), so 512 is provably above any legit block while a hostile
/// unclosed open cannot latch the exemption over the whole summary.
const _maxPinEnvelopeLines = 512;

/// Aliases of the renderer's envelope tags — single source of truth in
/// `structured/markers.dart` ([pinBlockOpenTag]/[pinBlockCloseTag]);
/// compile-time linked, so a renderer rename cannot silently orphan the
/// exemption (review gh-1409 round 2, suggestion 5).
const pinEnvelopeOpenTag = pinBlockOpenTag;
const pinEnvelopeCloseTag = pinBlockCloseTag;

/// Removes every `[context note …]` block — opened by a real bracket and
/// closed by a `]` within the same line or the two lines after it (LLM
/// summaries reflow notes at ~80 columns); an unterminated or far-closed
/// opener is prose that merely mentions a context note and is left
/// untouched. Removed spans are recorded as stripped.
String _stripContextNotes(String text, List<String> stripped) {
  final out = StringBuffer();
  var start = 0;
  for (final match in _contextNoteOpen.allMatches(text)) {
    if (match.start < start) continue; // opener inside a removed block
    final close = text.indexOf(']', match.end);
    final searchEnd = close < 0 ? text.length : close;
    final newlines = '\n'
        .allMatches(text.substring(match.end, searchEnd))
        .length;
    if (close < 0 || newlines > 2) continue;
    out.write(text.substring(start, match.start));
    var end = close + 1;
    // A note occupying a whole line takes its line break with it, so the
    // strip does not leave a blank line behind.
    if (end < text.length &&
        text[end] == '\n' &&
        (match.start == 0 || text[match.start - 1] == '\n')) {
      end++;
    }
    final removed = text.substring(match.start, end);
    if (removed.trim().isNotEmpty) stripped.add(removed.trim());
    start = end;
  }
  out.write(text.substring(start));
  return out.toString();
}

/// Strips ephemeral sentences from one [line]; `null` when nothing survives
/// (the line carried only ephemeral content and is dropped whole). A line
/// containing any of [protectedLines] verbatim (gh-1409 AC4: pinned skill
/// directives) is returned unchanged.
String? _sanitizeLine(
  String line,
  List<String> stripped,
  Set<String> protectedLines,
) {
  final pinKept = _pinProtectedLine(line, protectedLines);
  if (pinKept != null) return pinKept;
  final sentences = line.split(RegExp(r'(?<=[.!?])\s+'));
  final kept = _stripEphemeralSentences(sentences, stripped);
  if (kept == null) return line; // nothing stripped → byte-identical.
  if (kept.isEmpty) return null; // the line carried only ephemeral text.
  return _reassembleStrippedLine(line, kept.join(' '));
}

/// The gh-1409 AC4 guard: [line] survives verbatim when it contains any of
/// [protectedLines] (a pin carrying the summary must not be mangled by the
/// ephemeral-claim strips around it). `null` → not protected.
String? _pinProtectedLine(String line, Set<String> protectedLines) {
  for (final protected in protectedLines) {
    if (protected.isNotEmpty && line.contains(protected)) return line;
  }
  return null;
}

/// Drops the ephemeral-claim sentences ([_secondPerson] + [_ephemeralClaim])
/// from [sentences], recording each in [stripped]. `null` → nothing was
/// ephemeral (the caller keeps the line byte-identical).
List<String>? _stripEphemeralSentences(
  List<String> sentences,
  List<String> stripped,
) {
  final kept = <String>[];
  var removed = 0;
  for (final sentence in sentences) {
    if (_secondPerson.hasMatch(sentence) &&
        _ephemeralClaim.hasMatch(sentence)) {
      if (sentence.trim().isNotEmpty) stripped.add(sentence.trim());
      removed++;
      continue;
    }
    kept.add(sentence);
  }
  if (removed == 0) return null;
  return kept;
}

/// Reassembles a line whose ephemeral sentences were stripped: a bare
/// surviving list marker ("2." after its content was stripped) is noise
/// (`null` — the line drops), and a partially stripped bullet keeps its
/// marker so the list stays valid.
String? _reassembleStrippedLine(String line, String text) {
  if (RegExp(r'^\s*(?:[-*+]|\d+\.)$').hasMatch(text)) return null;
  final bullet = RegExp(r'^(\s*(?:[-*+]|\d+\.)\s+)');
  if (bullet.hasMatch(line) && !bullet.hasMatch(text)) {
    return bullet.firstMatch(line)!.group(1)! + text.trimLeft();
  }
  return text;
}

/// The structured compaction engine (issue #148).
///
/// Two passes, in order:
///
/// 1. **Hide** (reversible): a judge model reads the context ledger and
///    picks whole segments it deems safe to hide — stale scaffold noise,
///    superseded tool results, dead ends. Hidden records become one-line
///    markers at their original position, expandable on demand. The judge
///    runs again while the window is still over pressure (bounded).
/// 2. **Checkpoint** (summary): when pressure remains, the oldest
///    hideable range is summarized into a text checkpoint whose marker
///    lists every expand id it covers. Checkpoints nest up to the depth
///    cap; beyond that the deepest level folds into the new checkpoint.
///
/// On hard failure or residual overflow the engine reports failure and
/// the host falls back to the classic prefix compactor — the classic
/// summary then renders under structured projection as an opaque
/// `legacy-ckpt` marker segment (flowchart S7).
///
/// Failure-safety contract mirrors the classic engine: a failed pass
/// appends NOTHING; `state.messages` is only rebuilt after a successful
/// append.
library;

import 'dart:async';
import 'dart:math' show max, min;

import '../../agent/agent.dart' show AgentState;
import '../../cancel_token.dart' show CancelToken, CancelTokenSource;
import '../../session/session_record.dart';
import '../../session/session_tree.dart';
import '../../context.dart';
import '../../types.dart';
import '../compaction.dart';
import '../summary_sanitizer.dart';
import '../token_estimation.dart';
import 'judge.dart';
import 'judge_health.dart';
import 'ledger.dart';
import 'markers.dart';
import 'projection.dart';
import '../cache_policy.dart';
import '../../exceptions.dart' show CompactionException;

/// Progress surface for the structured engine.
abstract interface class StructuredCompactorHooks {
  /// The judge/summary stream tail (busy-row echo).
  void onDelta(String delta);

  /// A completed hide or checkpoint pass.
  void onPass(StructuredCompactionPass pass);
}

/// One hide or checkpoint pass outcome.
final class StructuredCompactionPass {
  const StructuredCompactionPass({
    required this.kind,
    required this.pass,
    required this.tokensBefore,
    required this.tokensAfter,
    required this.ok,
    this.error,
    this.judgeCalls = 0,
    this.hiddenCount = 0,
    this.summarizedCount = 0,
    this.summary,
    this.marginTokens,
    this.bandTokens,
    this.hideableRemaining,
    this.judgeInputEntries,
    this.judgeInputTokens,
    this.judgeElapsedMs,
    this.judgeLatched = false,
    this.basisReadTokens,
    this.durationMs,
    this.usage,
  });

  /// `'hide'`, `'hide-fallback'`, `'hide-lru'`, `'checkpoint'`,
  /// `'checkpoint-escalation'`, or `'skipped:judge-latch'`.
  final String kind;

  /// 1-based pass number within the run.
  final int pass;

  /// Estimated tokens before the pass.
  final int tokensBefore;

  /// Estimated tokens after the pass.
  final int tokensAfter;

  /// Whether the pass appended state.
  final bool ok;

  /// The error that failed the pass, when [ok] is `false`.
  final Object? error;

  /// LLM calls this pass consumed (AC5 instrumentation).
  final int judgeCalls;

  /// Records hidden this pass (hide passes).
  final int hiddenCount;

  /// Message records folded into the checkpoint (checkpoint passes).
  final int summarizedCount;

  /// The checkpoint text this pass wrote; `null` for hide passes.
  final String? summary;

  /// gh-2044 fragile-band escalation (optional metadata, never content):
  /// the settled margin `trigger - tokensBefore` that triggered the
  /// escalation pass. Null on every other pass kind.
  final int? marginTokens;

  /// gh-2044: the band the margin was measured against
  /// (`settings.reserveTokens`). Null on every other pass kind.
  final int? bandTokens;

  /// gh-2044: remaining hideable-entry count at escalation time — a
  /// diagnostic count only (the rejected "hides exhausted" gate must not
  /// grow back as a hidden precondition). Null on every other pass kind.
  final int? hideableRemaining;

  /// gh-2096 timeout diagnosis (judge-failure and probe receipts): the
  /// attempt shape — the rendered judge input's entry count. Null on
  /// every other pass kind.
  final int? judgeInputEntries;

  /// gh-2096: the rendered judge input's estimated token size. Null on
  /// every other pass kind.
  final int? judgeInputTokens;

  /// gh-2096: the wall-clock time the judged attempt consumed. Null on
  /// every other pass kind.
  final int? judgeElapsedMs;

  /// gh-2096: whether this pass was decided by the cross-run judge-health
  /// latch (a latched skip or a probe receipt). Never content — a count
  /// and a flag only, like the escalation metadata above.
  final bool judgeLatched;

  /// gh-2097: the upward basis jump this pass's post-append re-read
  /// revealed. A pass appends only shrinkers (hidden ranges, a
  /// checkpoint), so an after-count above its before-count is the
  /// session projection holding MORE than the in-memory view did at
  /// measurement time (a second writer appending between the two
  /// measurements) — a measurement-basis change, never a compaction
  /// regression. The report renders it as `basis re-read: +N` instead
  /// of a clamped `0 freed`. Null when the re-read landed on the same
  /// basis. A count only, never content.
  final int? basisReadTokens;

  /// gh-2101: the pass's wall-clock duration (milliseconds) — the
  /// one-line report's latency metric. Null on unmeasured receipts.
  final int? durationMs;

  /// gh-2101: the metered usage of the LM calls this pass consumed (call
  /// count, token breakdown, cost) — the details report's cost/cache-hit
  /// metrics. Null when the pass made no metered call (or no usage was
  /// reported).
  final CompactionUsageTotals? usage;
}

/// Rebuilds [state.messages] from the session projection. gh-2237: the
/// projection is the single anchor authority — `buildContextMessages`
/// already normalizes usage with the stale-anchor curation
/// (`_resetStaleUsageAnchors`: boundary-keyed resets, plus head-truncated
/// boundary-less tails whose persisted anchors price a context the
/// projection no longer renders — the windowed-resume window edge), so
/// this rebuild must NOT blanket-zero anchors. Zeroing here re-derived a
/// collapsed chars/4 basis where the arming gate had measured a
/// usage-anchored over-trigger basis: the run exited under-trigger with
/// zero passes, zero receipts, and the gate re-fired every turn (the
/// silent auto-compact loop). Anchors travel with the data — and an
/// anchor the resident tail cannot vouch for travels reset, so the gate
/// basis and this rebuild's basis stay ONE measurement even after a
/// boundary-less windowed resume. The ONE refresh both the engine passes
/// and the agent-initiated hide use (issue #1379 tier 2) — a single
/// contract, not two copies.
Future<void> refreshAgentState(Session session, AgentState state) async {
  state.messages = await session.buildContextMessages();
}

/// The structured compaction engine.
final class StructuredCompactor {
  /// Creates a compactor over [session]/[state].
  StructuredCompactor({
    required this.session,
    required this.state,
    required this.window,
    required this.settings,
    required this.judge,
    required this.summarize,
    required this.checkpointPrompt,
    this.hooks,
    this.maxHidePasses = 3,
    this.maxCheckpointPasses = 4,
    this.protectLastN = hideProtectTailEntries,
    this.depthCap = 4,
    this.summarizerWindow,
    this.cancelToken,
    this.budgetSource,
    this.attemptBudget = const Duration(seconds: 300),
    this.judgeTarget = 'role=default',
    this.judgeProbeAfter = const Duration(minutes: 10),
    this.pinnedOperativeBlock,
    this.pinnedLines = const {},
    this.usage,
  });

  /// The session being compacted.
  final Session session;

  /// The agent state whose `messages` get refreshed after each pass.
  final AgentState state;

  /// The conversation window in tokens.
  final int window;

  /// Compaction thresholds (reserve / keep-recent).
  final CompactionSettings settings;

  /// The hide judge (pass 1).
  final HideJudgeFn judge;

  /// The summarizer (pass 2).
  final SummarizeFn summarize;

  /// The checkpoint instruction tail (from the prompt file).
  final String checkpointPrompt;

  /// Optional progress hooks.
  final StructuredCompactorHooks? hooks;

  /// gh-2237: WHY the last [run] returned without doing any work — the
  /// deciding gate plus the basis/trigger numbers, rendered by the host
  /// into the zero-pass terminal receipt (`auto-compact done passes=0
  /// (no-op: …)`). Null when the run did work (its passes carry their
  /// own receipts) or failed; cleared at every [run] start.
  String? exitReason;

  /// Bound on judge iterations per run.
  final int maxHidePasses;

  /// Bound on checkpoint iterations per run.
  final int maxCheckpointPasses;

  /// How many trailing ledger entries are never hidden.
  final int protectLastN;

  /// Maximum checkpoint nesting depth before flattening.
  final int depthCap;

  /// The summarizer model's own context window (issue #729) — the smol
  /// role's when it differs from the main model's. `null` falls back to
  /// [window]; when set, a checkpoint prompt that would not fit the
  /// summarizer's payload budget is summarized CHUNK-WISE (each chunk's
  /// summary threaded into the next as a `<folded-checkpoint>`), so no
  /// summarization request ever exceeds the summarizer's window.
  final int? summarizerWindow;

  /// Cancellation for the LLM calls.
  final CancelToken? cancelToken;

  /// Writable side of the token the factory handed to the judge and
  /// summarizer adapters; the attempt/total budgets cancel it so a wedged
  /// call dies at the provider layer (issue #515).
  final CancelTokenSource? budgetSource;

  /// Wall-clock budget for ONE judge/summarizer call (issue #515). The
  /// call site's host watchdogs are disarmed by the time compaction runs,
  /// so a provider that accepts the request and never answers must die
  /// here: on expiry the budget token aborts the underlying HTTP call and
  /// a named [TimeoutException] fails the run.
  final Duration attemptBudget;

  /// Who the judge call talks to, for the named failure line (issue
  /// #541 AC3): `role=smol, model=kimi-k2 @ gate.example.ai` — a dead
  /// judge must never surface as an anonymous TimeoutException.
  final String judgeTarget;

  /// gh-2096: how long a latched judge goes unprobed. While the
  /// cross-run health latch holds, every run takes the deterministic
  /// hide and pays NO judge budget; once this window has elapsed since
  /// the newest health record — or the configured class changed, which
  /// probes at once — the run pays ONE probe call: success unlatches,
  /// failure re-arms the window. The budget tax becomes once per window
  /// instead of once per run.
  final Duration judgeProbeAfter;

  /// gh-1409 E7: the rendered PINNED OPERATIVE LINES block (verbatim-
  /// preserve duty) inserted into every checkpoint prompt. `null` →
  /// prompts are byte-identical to the pre-pin engine (F4 compat guard).
  final String? pinnedOperativeBlock;

  /// gh-1409 AC4: the raw pin lines the sanitizer protects when healing
  /// folded checkpoints re-entering the prompt.
  final Set<String> pinnedLines;

  /// gh-2101: the run's LM usage ledger — the factory wires ONE ledger
  /// shared by the judge and digest adapters; the engine folds per-pass
  /// deltas into the pass receipts. `null` keeps the legacy shape (no
  /// metrics).
  final CompactionUsageAccumulator? usage;

  /// Consecutive judge failures before the deterministic fallback hide
  /// engages (issue #541): one retry, then the judge-less hide. The
  /// threshold itself is [judgeLatchAfter] — the same count persists
  /// across runs through the health latch (gh-2096).
  int _consecutiveJudgeFailures = 0;

  /// gh-2096: the persisted cross-run judge-health state (the newest
  /// `structured_judge_health` record on the branch) and whether the
  /// latch currently holds. Loaded at the start of every hide-pass run.
  JudgeHealthState _judgeHealth = JudgeHealthState.fresh;
  bool _judgeLatched = false;

  /// The token passed into every LLM call: the budget source when the
  /// factory provided one, else the plain external [cancelToken].
  CancelToken? get _effectiveToken => budgetSource?.token ?? cancelToken;

  int _pass = 0;

  /// Issue #1499: per-run ledger entry memo — the judge/LRU/checkpoint
  /// passes each rebuild the ledger over the whole visible path, and the
  /// memo turns every rebuild after the first into O(changed records)
  /// instead of re-tokenizing the session's history.
  final LedgerEntryCache _ledgerCache = LedgerEntryCache();

  /// The live request-size estimate in the ONE basis the ctx meter, the
  /// loop's over-window guard, and the classic compactor all enforce:
  /// transcript estimate plus the system-prompt / tool-schema overhead
  /// whenever no provider-usage anchor prices them in.
  int _requestTokens() => estimateRequestTokens(
    state.messages,
    systemPrompt: state.systemPrompt,
    tools: state.tools,
  );

  /// Runs both passes; returns whether the context settled at or below
  /// the trigger — `true` when the pressure is resolved, `false` when
  /// residual overflow remains and the host falls back to the classic
  /// compactor. A zero-pass `true` outcome carries [exitReason] — the
  /// deciding gate (gh-2237) — so the host can close the receipt chain
  /// honestly.
  Future<bool> run({bool force = false}) async {
    exitReason = null;
    if (window <= 0) {
      exitReason = 'window disabled (window <= 0)';
      return true;
    }
    // gh-2097: re-anchor the agent state from the session projection
    // BEFORE any trigger/before/over math. The in-memory transcript can
    // lag the session file (an in-memory tail cut, a second writer
    // appending to the same session between runs) — the stale basis
    // computed `over` ≈ 1.4k where ~177k was needed and every pass of
    // the run under-sized against it. One projection build, bounded by
    // the ledger cache (O(changed records)).
    await _refreshState();
    final trigger = window - settings.reserveTokens;
    if (!force) {
      // gh-2237: this is the exit that powered the silent loop — the
      // engine deciding "nothing to do" against a basis the arming gate
      // never measured. The reason rides [exitReason] into the host's
      // terminal receipt. The basis binds once: the reason renders the
      // SAME measurement the gate compared (gh-2237 rework review — one
      // O(context) estimate, not two).
      final basis = _requestTokens();
      if (basis <= trigger) {
        exitReason = 'basis $basis below trigger $trigger (trigger gate)';
        return true;
      }
    }
    // Tier 2 LRU re-hide (issue #1379): evict least-recently-used
    // expansion artifacts first — the oldest expand call/result pairs
    // re-fold into markers before the judge ever sees the ledger.
    await _runLruRehidePasses(trigger);
    if (!await _runHidePasses(trigger)) return false;
    if (!await _runCheckpointPasses(trigger)) return false;
    // gh-2044 fragile-band escalation: an automatic run that settled with
    // less than one full reserve of headroom deepens once through the
    // checkpoint machinery, whether or not hideable entries remain. The
    // deterministic fallback (issue #541) and the pass loops stop at the
    // trigger, so a degraded run ducks under by a sliver and the next
    // turn or two crosses the trigger again (sid 01a17c9c). Forced runs —
    // manual `/compact` and the message-cap channel (`force || cap`) —
    // keep their existing behavior; `maxCheckpointPasses == 0` keeps
    // meaning "no checkpoint work".
    if (!force && maxCheckpointPasses > 0) {
      final settled = _requestTokens();
      final margin = trigger - settled;
      if (margin >= 0 && margin < settings.reserveTokens) {
        if (!await _runCheckpointEscalationPass(trigger, margin)) {
          return false;
        }
      }
    }
    return _requestTokens() <= trigger;
  }

  /// Tier 2 LRU re-hide (issue #1379): after an expand storm, the oldest
  /// expand call/result pairs re-fold into markers at the next pressure
  /// event — the newest expansion is always kept. LRU order is derived
  /// from file order alone (an expansion's recency IS its record position;
  /// nothing extra is stored), so replay is deterministic. The re-hidden
  /// segments themselves never left hidden-but-expandable state — their
  /// markers stay in the session — so the lossless invariant (#148 AC2)
  /// is untouched.
  Future<void> _runLruRehidePasses(int trigger) async {
    if (_ladderTerminated) return;
    final before = _requestTokens();
    final over = before - trigger;
    if (over <= 0) return;
    final view = await _buildView();
    if (view == null) return;
    final groups = _rehideCandidates(view);
    if (groups.length <= 1) return;
    final evictions = _pickRehideEvictions(
      groups,
      over,
      protectedTailIds(view.ledger, protectLastN),
      view.state.pinnedRecordIds,
    );
    if (evictions.isEmpty) return;
    final watch = Stopwatch()..start();
    final usageBefore = usage?.snapshot();
    await session.appendHiddenRange(recordIds: evictions.toList()..sort());
    // #2258: a kill landing while the append was in flight leaves the
    // record written-but-unprojected — skip the refresh and the receipt;
    // the factory's local trim stays the tail (resume replays the record).
    if (_ladderTerminated) return;
    final after = await _refreshState();
    hooks?.onPass(
      StructuredCompactionPass(
        kind: 'hide-lru',
        pass: ++_pass,
        tokensBefore: before,
        tokensAfter: after,
        ok: true,
        judgeCalls: 0,
        hiddenCount: evictions.length,
        basisReadTokens: _basisFlip(before, after),
        durationMs: watch.elapsedMilliseconds,
        usage: _usageDelta(usageBefore),
      ),
    );
  }

  /// The visible expand-carrier groups oldest-first — the LRU eviction
  /// candidates (issue #1379 tier 2): every visible assistant carrier of
  /// a compact_expand call as its whole pair group, newest last.
  List<(int, Set<String>, int)> _rehideCandidates(_LedgerView view) {
    final byId = {for (final record in view.path) record.id: record};
    final candidates = <(int, Set<String>, int)>[];
    for (final record in view.path) {
      final message = _rehideCandidateMessage(view, record);
      if (message == null || !_isExpandCarrier(message)) continue;
      final (group, tokens, hasResult) = _carrierGroupWeight(
        view,
        byId,
        record.id,
      );
      // An unanswered carrier (no result yet) is not an expansion —
      // hiding it would orphan a live tool call on the wire (#85).
      if (!hasResult) continue;
      candidates.add((view.seqs.seqOf(record.id) ?? 0, group, tokens));
    }
    candidates.sort((a, b) => a.$1.compareTo(b.$1));
    return candidates;
  }

  /// The carrier [AssistantMessage] when [record] is a re-hide candidate
  /// at all — a visible assistant record (never hidden, never
  /// checkpoint-covered). Null otherwise.
  AssistantMessage? _rehideCandidateMessage(
    _LedgerView view,
    SessionRecord record,
  ) {
    final message = record is MessageRecord ? record.message : null;
    if (message is! AssistantMessage) return null;
    if (view.state.hiddenRecordIds.contains(record.id)) return null;
    if (view.state.isCovered(record.id)) return null;
    return message;
  }

  /// Whether [message] carries a compact_expand tool call.
  bool _isExpandCarrier(AssistantMessage message) => message.content.any(
    (block) => block is ToolCall && block.name == compactExpandToolName,
  );

  /// The candidate's whole pair group with its token weight and whether a
  /// result message rode along (#85 pair integrity).
  (Set<String>, int, bool) _carrierGroupWeight(
    _LedgerView view,
    Map<String, SessionRecord> byId,
    String carrierId,
  ) {
    final ledger = view.ledger;
    final group = ledger.groupOf(carrierId);
    var tokens = 0;
    var hasResult = false;
    for (final id in group) {
      final other = byId[id];
      if (other is MessageRecord && other.message is ToolResultMessage) {
        hasResult = true;
      }
      final seq = view.seqs.seqOf(id);
      if (seq != null) tokens += ledger.entryAtSeq(seq)?.tokens ?? 0;
    }
    return (group, tokens, hasResult);
  }

  /// The groups to re-fold now: oldest first until [over] tokens are
  /// freed, never touching the newest group, the protected tail, or a
  /// pinned expansion (AC3).
  Set<String> _pickRehideEvictions(
    List<(int, Set<String>, int)> groups,
    int over,
    Set<String> protectedTail,
    Set<String> pinnedRecordIds,
  ) {
    final ids = <String>{};
    var freed = 0;
    for (final (_, group, tokens) in groups.take(groups.length - 1)) {
      if (freed >= over) break;
      // The protected tail holds here exactly as in the judge path, and a
      // pinned expansion stays on the wire (AC3).
      if (group.any(protectedTail.contains)) continue;
      if (group.any(pinnedRecordIds.contains)) continue;
      ids.addAll(group);
      freed += tokens;
    }
    return ids;
  }

  /// gh-2044: the total-budget latch. [cancelBudget] is the factory's
  /// total-budget race kill (issue #515) — the ONE caller — so once it
  /// fires the run's outcome is the factory's authoritative timeout path:
  /// the escalation must not start another attempt after budget
  /// exhaustion, and must not append (nor report) after that outcome.
  /// Deliberately separate from [budgetSource]: per-call attempt-budget
  /// kills cancel the budget token too, and the incident's judge timeouts
  /// must not suppress the escalation (gh-2044 AC1).
  final CancelTokenSource _totalBudgetSource = CancelTokenSource();

  /// Whether the factory's total-budget race has killed this run.
  bool get _totalBudgetSpent => _totalBudgetSource.token.isCancelled;

  /// Cancels the budget token — the factory's total-budget race calls
  /// this so the wedged call dies at the provider layer.
  void cancelBudget(Object? reason) {
    budgetSource?.cancel(reason);
    _totalBudgetSource.cancel(reason);
  }

  /// gh-2044: whether a user/run cancellation killed this run — checked
  /// around the escalation so a cancelled deepening surfaces the abort
  /// (issue #1085 parity) instead of dissolving into "optional pass
  /// failed, success stands". The budget token latches per-call budget
  /// kills too (issue #515 provider-layer aborts carry a
  /// [TimeoutException] reason) — those are NOT cancels: the incident's
  /// judge timeouts must still escalate. Any other reason reached this
  /// token only through the factory's run-token link — a user abort.
  bool get _runCancelled {
    if (cancelToken?.isCancelled ?? false) return true;
    final source = budgetSource;
    if (source == null) return false;
    return source.token.isCancelled &&
        source.token.cancelReason is! TimeoutException;
  }

  /// The named [TimeoutException] a budget expiry throws (issue #515).
  TimeoutException _budgetTimeout(String what, Duration budget) =>
      TimeoutException(
        'structured compaction $what exceeded the '
        '${budget.inSeconds}s budget (issue #515)',
        budget,
      );

  /// #2258: the terminal write gate every pass ladder checks before it
  /// appends, refreshes or reports. Both signals are terminal and first
  /// wins: the factory's total-budget verdict (`cancelBudget` — the #515
  /// kill) and a run cancellation (#1085). A ladder that lost the race to
  /// the factory's verdict must not append session records, refresh
  /// `state.messages` (the verdict's local trim stays the authoritative
  /// tail) or report a pass — it stops silent and the run surfaces
  /// abandoned.
  bool get _ladderTerminated => _runCancelled || _totalBudgetSpent;

  /// A missing projection and a projection with no hide candidates are both
  /// successful terminal verdicts for the hide ladder.
  _LedgerView? _viewWithHideableEntries(_LedgerView? view) =>
      view == null || _hideableEntries(view.ledger).isEmpty ? null : view;

  Future<bool> _runHidePasses(int trigger) async {
    // gh-2096: the consecutive-failure counter is PERSISTED per session —
    // it seeds from the newest judge-health record instead of resetting
    // every run (the incident re-paid the full budget on every run for as
    // long as the configured class stayed slow).
    final health = await _loadJudgeHealth();
    _judgeHealth = health;
    _consecutiveJudgeFailures = health.consecutiveFailures;
    _judgeLatched = health.latched;
    for (var i = 0; i < maxHidePasses; i++) {
      // #2258: the verdict may have landed between iterations.
      if (_ladderTerminated) return false;
      final before = _requestTokens();
      if (before <= trigger) {
        exitReason =
            'basis $before below trigger $trigger '
            '(hide-pass gate)';
        return true;
      }
      final builtView = await _buildView();
      final view = _viewWithHideableEntries(builtView);
      if (view == null) {
        if (builtView == null) {
          exitReason = 'projection view unavailable (hide-pass gate)';
        }
        return true;
      }

      // gh-2096: the cross-run latch gate — while latched the judge
      // contributes nothing unless the probe window elapsed (or the
      // configured class changed, which probes at once). This run makes
      // exactly one judge decision, then the deterministic hide decides;
      // a non-null gate result is that decision — both skip outcomes
      // converge on the loop's own successful-verdict return.
      if (await _latchedGate(trigger, before) != null) return true;

      // gh-2101: the pass's measured window opens HERE — the judge call,
      // its parse and the hide append all belong to the pass's duration
      // and usage.
      final watch = Stopwatch()..start();
      final usageBefore = usage?.snapshot();
      final attempt = await _runHideAttempt(
        trigger,
        view,
        before,
        watch,
        usageBefore,
      );
      // #2258: the gate fired mid-attempt — the run surfaces abandoned.
      if (attempt.killed) return false;
      // A decided attempt (a counted judge failure, a latched skip, an
      // empty or fully-vetoed pick list) ends the loop on the loop's own
      // successful-verdict return — identical to the pre-extraction
      // break/return-true exits.
      if (attempt.decided) return true;
    }
    return true;
  }

  /// One judge hide attempt (gh-2101 pass window): the judge call, its
  /// parse, the failure/fallback ladder and — on a hideable verdict — the
  /// append, refresh and receipt. Extracted so [_runHidePasses] keeps its
  /// iteration flow only (CRAP ratchet); behavior is byte-identical to
  /// the inline loop body it replaced.
  ///
  /// Returns [killed] when the #2258 terminal gate fired mid-attempt (the
  /// loop surfaces abandoned, `false`) and [decided] when the attempt
  /// settled the run on the loop's own successful-verdict return (`true`
  /// — the counted-failure and empty-pick exits). Neither flag: keep
  /// iterating.
  Future<({bool killed, bool decided})> _runHideAttempt(
    int trigger,
    _LedgerView view,
    int before,
    Stopwatch watch,
    CompactionUsageTotals? usageBefore,
  ) async {
    final call = await _callJudge(view);
    // #2258: the total-budget kill lands while the judge hangs — the
    // factory's timeout verdict + local trim is authoritative, so this
    // ladder must not count the kill as an ordinary judge failure
    // (no receipt, no latch write, no deterministic hide), hide, or
    // refresh after it.
    if (_ladderTerminated) return (killed: true, decided: false);
    // F1: a failed judge call hides nothing — but since #541 it is
    // COUNTED, not fatal: one retry, then the deterministic
    // judge-less hide, so a dead judge can no longer brick the run.
    // A garbage answer decided nothing — a failure like any other.
    final picks = call.failure == null ? parseHidePicks(call.answer!) : null;
    if (picks == null) {
      final continues = await _handleJudgeFailure(
        trigger,
        call.failure ??
            const CompactionException(
              'hide judge returned an unparseable answer',
            ),
        shape: call.shape,
      );
      return (killed: false, decided: !continues);
    }
    _consecutiveJudgeFailures = 0;
    // gh-2096: a parsed answer is a live judge — clear the persisted
    // latch (additive unlatch record; a no-op write when the session
    // was never unhealthy, keeping the legacy flow write-free).
    await _recordJudgeSuccess();
    if (picks.isEmpty) return (killed: false, decided: true);
    final ids = validateHidePicks(
      picks,
      view.ledger,
      protectLastN: protectLastN,
      pinnedRecordIds: view.state.pinnedRecordIds,
    );
    if (ids.isEmpty) return (killed: false, decided: true);
    await session.appendHiddenRange(recordIds: ids.toList()..sort());
    // #2258: see _runLruRehidePasses — written-but-unprojected stops
    // here; the verdict's local trim stays the tail.
    if (_ladderTerminated) return (killed: true, decided: false);
    final after = await _refreshState();
    hooks?.onPass(
      StructuredCompactionPass(
        kind: 'hide',
        pass: ++_pass,
        tokensBefore: before,
        tokensAfter: after,
        ok: true,
        judgeCalls: 1,
        hiddenCount: ids.length,
        basisReadTokens: _basisFlip(before, after),
        durationMs: watch.elapsedMilliseconds,
        usage: _usageDelta(usageBefore),
      ),
    );
    return (killed: false, decided: false);
  }

  /// gh-2096: the cross-run latch gate. While latched the judge
  /// contributes nothing this run unless the probe window elapsed (or
  /// the configured class changed, which probes at once): the skip
  /// receipt names the consequence ("budget unwinnable for the
  /// configured class") and the deterministic hide decides. Returns
  /// `null` when the judge may be called; a non-null result means the
  /// run is decided — the skip's outcomes converge on the same
  /// successful-verdict return the loop's natural end produces.
  Future<bool?> _latchedGate(int trigger, int before) async {
    if (!_judgeLatched || _latchedProbeDue) return null;
    return _latchedSkipHide(trigger, before);
  }

  /// One counted judge failure (issue #541 F1): a failed call or a
  /// garbage answer decides nothing — it is COUNTED, not fatal. Returns
  /// whether the hide-pass loop continues. While latched the call WAS
  /// the one probe-per-window: the probe paid the budget and lost, so
  /// count + persist, then the deterministic hide decides — NO retry
  /// (the retry ladder is the tax the latch exists to end) and the run
  /// is decided either way. A fresh failure retries toward
  /// [judgeLatchAfter] and the deterministic judge-less hide; `false`
  /// means that hide decided against continuing — the run ends with the
  /// loop's own successful verdict.
  Future<bool> _handleJudgeFailure(
    int trigger,
    Object failure, {
    JudgeAttemptShape? shape,
  }) async {
    if (_judgeLatched) {
      await _persistProbeFailure();
      await _registerJudgeFailure(
        trigger,
        failure,
        shape: shape,
        latched: true,
      );
      return false;
    }
    return _registerJudgeFailure(trigger, failure, shape: shape);
  }

  /// One judge call under the attempt budget (issue #515). A budget
  /// expiry cancels the budget token — aborting the wedged provider
  /// call — but since #541 it is a JUDGE failure, not a run failure:
  /// the caller counts it and falls toward the deterministic hide.
  ///
  /// gh-2096: the call runs under a PER-CALL child token — a timeout
  /// aborts ONLY the in-flight call, while the retry and the later LM
  /// stages of the run keep a live token (the incident's retry was born
  /// cancelled: the run-wide budget token died with the first timeout
  /// and every later call failed in ~75 ms). The attempt's measured
  /// shape — input entries, estimated tokens, elapsed — rides every
  /// failure receipt.
  Future<({String? answer, Object? failure, JudgeAttemptShape shape})>
  _callJudge(_LedgerView view) async {
    final ledgerText = view.ledger.render();
    final perCall = CancelTokenSource();
    // gh-2096: forward the run-wide token's cancel (a user abort, a
    // total-budget kill) into the in-flight call; a per-call budget
    // expiry cancels ONLY the child — the retry and later stages keep a
    // live parent. One listener per call, bounded by the pass caps.
    final parent = _effectiveToken;
    if (parent != null) {
      unawaited(
        parent.onCancel.then((_) => perCall.cancel(parent.cancelReason)),
      );
    }
    JudgeAttemptShape shapeOf(Duration elapsed) => (
      entries: min(
        view.ledger.entries.length,
        ContextLedger.judgePreviewEntries,
      ),
      tokens: estimateStringTokens(ledgerText),
      elapsed: elapsed,
    );
    final watch = Stopwatch()..start();
    try {
      final answer = await judge(ledgerText, perCall.token).timeout(
        attemptBudget,
        onTimeout: () {
          final timeout = _judgeTimeout(shapeOf(watch.elapsed));
          // gh-2096: the child token dies — the parent (the retry and
          // the summarizer stages) stays live.
          perCall.cancel(timeout);
          throw timeout;
        },
      );
      watch.stop();
      // HideJudgeFn contract: null IS a failed call (F1) — count it.
      return (
        answer: answer,
        failure: answer == null
            ? const CompactionException('hide judge failed call')
            : null,
        shape: shapeOf(watch.elapsed),
      );
    } on Object catch (error) {
      watch.stop();
      // Timeout and adapter/provider failures alike: a judge failure like
      // any other; the run must not die on it.
      return (answer: null, failure: error, shape: shapeOf(watch.elapsed));
    }
  }

  /// Records a judge failure (issue #541): a named pass report, then —
  /// after [judgeLatchAfter] consecutive failures — the deterministic
  /// judge-less hide. gh-2096: the failure receipt carries the attempt
  /// [shape] and the [latched] flag, and the threshold crossing PERSISTS
  /// the latch (an additive record) so the next run skips the judge.
  /// Returns whether the hide loop continues.
  Future<bool> _registerJudgeFailure(
    int trigger,
    Object error, {
    JudgeAttemptShape? shape,
    bool latched = false,
  }) async {
    _consecutiveJudgeFailures++;
    final tokens = _requestTokens();
    hooks?.onPass(
      StructuredCompactionPass(
        kind: 'hide',
        pass: ++_pass,
        tokensBefore: tokens,
        tokensAfter: tokens,
        ok: false,
        error: error,
        judgeInputEntries: shape?.entries,
        judgeInputTokens: shape?.tokens,
        judgeElapsedMs: shape?.elapsed.inMilliseconds,
        judgeLatched: latched,
      ),
    );
    if (_consecutiveJudgeFailures < judgeLatchAfter) return true;
    if (!_judgeLatched) {
      // The latch engages NOW: persist it (best-effort) so the next run
      // takes the deterministic hide without re-paying the budget, and
      // mirror the state in memory (a still-over run keeps skipping).
      await _persistJudgeHealth(
        consecutiveFailures: _consecutiveJudgeFailures,
        target: judgeTarget,
      );
      _judgeLatched = true;
      _judgeHealth = JudgeHealthState(
        consecutiveFailures: _consecutiveJudgeFailures,
        target: judgeTarget,
        updatedAt: DateTime.now(),
      );
    }
    return _deterministicHide(trigger);
  }

  /// gh-2096: whether the latched judge gets its probe this run — the
  /// probe window elapsed since the newest health record, or the
  /// configured class changed since the latch (a new class deserves an
  /// immediate chance; the latch is about the class, not the session).
  bool get _latchedProbeDue {
    final health = _judgeHealth;
    final target = health.target;
    if (target != null && target != judgeTarget) return true;
    final updated = health.updatedAt;
    if (updated == null) return true;
    return DateTime.now().difference(updated) >= judgeProbeAfter;
  }

  /// gh-2096: the latched skip — the judge contributes nothing this run.
  /// The receipt names the consequence explicitly ("budget unwinnable
  /// for the configured class"), then the deterministic hide decides.
  /// Issue #2274: the kind is distinguishable (`skipped:judge-latch`) —
  /// a DESIGNED skip is not a failure, so the host hooks render it as a
  /// non-failure line instead of a FAILED one.
  Future<bool> _latchedSkipHide(int trigger, int before) async {
    hooks?.onPass(
      StructuredCompactionPass(
        kind: 'skipped:judge-latch',
        pass: ++_pass,
        tokensBefore: before,
        tokensAfter: before,
        ok: false,
        error: CompactionException(
          'judge latched: budget unwinnable for the configured class '
          '(consecutive judge failures: $_consecutiveJudgeFailures) — '
          'skipping the judge this run (gh-2096)',
        ),
        judgeLatched: true,
      ),
    );
    return _deterministicHide(trigger);
  }

  /// gh-2096: the probe's failure count grew — persist it (best-effort)
  /// and re-arm the probe window before the fallback decides the run.
  Future<void> _persistProbeFailure() async {
    await _persistJudgeHealth(
      consecutiveFailures: _consecutiveJudgeFailures + 1,
      target: judgeTarget,
    );
    _judgeHealth = JudgeHealthState(
      consecutiveFailures: _consecutiveJudgeFailures + 1,
      target: judgeTarget,
      updatedAt: DateTime.now(),
    );
  }

  /// gh-2096: a parsed judge answer is a live judge — persist the
  /// unlatch when the session was ever unhealthy. A legacy session
  /// (never latched) writes nothing, keeping the healthy flow
  /// byte-identical.
  Future<void> _recordJudgeSuccess() async {
    if (!_judgeLatched && _judgeHealth.consecutiveFailures == 0) return;
    _judgeLatched = false;
    _judgeHealth = JudgeHealthState.fresh;
    await _persistJudgeHealth(consecutiveFailures: 0, target: judgeTarget);
  }

  /// Loads the persisted judge-health state from the branch path
  /// (gh-2096). A read failure degrades to fresh — the latch must never
  /// fail a run.
  Future<JudgeHealthState> _loadJudgeHealth() async {
    try {
      return judgeHealthFromPath(await session.getBranch()) ??
          JudgeHealthState.fresh;
    } on Object catch (_) {
      return JudgeHealthState.fresh;
    }
  }

  /// Appends the additive health record (gh-2096). Best-effort: a sealed
  /// or read-only session keeps its in-memory decision and never fails
  /// the compaction over the latch bookkeeping.
  Future<void> _persistJudgeHealth({
    required int consecutiveFailures,
    String? target,
  }) async {
    try {
      await session.appendCustomEntry(
        customType: judgeHealthRecordType,
        data: judgeHealthPayload(
          consecutiveFailures: consecutiveFailures,
          target: target,
        ),
      );
    } on Object catch (_) {
      // Best-effort by contract — see the doc comment.
    }
  }

  /// The deterministic judge-less hide (issue #541): the judge is down
  /// after N consecutive failures — hide oldest-first, whole pair
  /// groups, past the recency floor, until the request fits under the
  /// trigger again. No LLM: the session always makes progress, even
  /// with every judge endpoint dark.
  Future<bool> _deterministicHide(int trigger) async {
    // #2258: the token-only guard could not see the total-budget kill
    // (a budget token is the kill signal, not a suggestion) — the gate
    // covers it and the run cancellation alike.
    if (_ladderTerminated) return false;
    final view = await _buildView();
    if (view == null) return false;
    final ledger = view.ledger;
    final before = _requestTokens();
    final over = before - trigger;
    final protectedTail = protectedTailIds(ledger, protectLastN);
    final tokensById = {
      for (final entry in ledger.entries) entry.recordId: entry.tokens,
    };
    final ids = <String>{};
    var freed = 0;
    for (final entry in ledger.entries) {
      if (freed >= over) break;
      if (entry.exempt ||
