    try {
      final stream = policy.runWith(
        () => streamFunction(
          model,
          Context(
            systemPrompt: system,
            messages: [UserMessage.text(ledgerText)],
          ),
          cancelToken: cancelToken,
        ),
        CompactionCallClass.judge,
      );
